window.BANCO = window.BANCO || [];
window.BANCO.push({"id": "tema3", "nombre": "Tema 3 · Las Cortes Generales", "bloques": [{"id": "t3-composicion", "nombre": "Composición, estatuto y funcionamiento (arts. 66 a 80)"}, {"id": "t3-leyes", "nombre": "Elaboración de las leyes (arts. 81 a 92)"}, {"id": "t3-tratados", "nombre": "Tratados internacionales (arts. 93 a 96)"}, {"id": "t3-control", "nombre": "Relaciones con el Gobierno y Reglamento del Congreso"}], "calendarios": {}, "casos": [], "preguntas": [{"id": "ce-155", "origen": "oficiales", "test": "INAP mayo 2026", "n": 3, "enunciado": "De acuerdo con el artículo 67 de la Constitución Española de 1978:", "opciones": ["Nadie podrá ser miembro de las dos Cámaras simultáneamente.", "Nadie podrá ser miembro de las dos Cámaras simultáneamente, salvo el Presidente del Gobierno y los Ministros.", "Nadie podrá ser miembro de las dos Cámaras simultáneamente, salvo el Presidente del Gobierno.", "Nadie podrá ser miembro de las dos Cámaras simultáneamente, pero se podrá acumular el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso."], "bloque": "t3-composicion", "precepto": "Artículo 67.1 CE", "correcta": 0, "justificaciones": ["Es esta. Es la primera prohibición del 67.1, tal cual, sin excepciones añadidas.", "No. El 67.1 no exceptúa a nadie: tampoco al Presidente del Gobierno ni a los Ministros.", "No. Mismo invento: no hay excepción para el Presidente del Gobierno.", "No. Justo al revés. El 67.1 prohíbe expresamente acumular el acta autonómica con la de Diputado al Congreso."], "arts": [67], "citas": [{"texto": "«Nadie podrá ser miembro de las dos Cámaras simultáneamente, ni acumular el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso.»", "fuente": "Artículo 67.1 CE"}], "truco": "El 67.1 son dos prohibiciones seguidas y ninguna admite excepción. Si una opción abre la puerta a alguien, es falsa."}, {"id": "ce-161", "origen": "oficiales", "test": "INAP julio 2026 (extraordinario)", "n": 3, "enunciado": "Conforme al artículo 68 de la Constitución Española de 1978, el Congreso de los Diputados se compone de:", "opciones": ["Un mínimo de 300 y un máximo de 400 diputados.", "Un mínimo de 350 y un máximo de 400 diputados.", "Un mínimo de 250 y un máximo de 350 diputados.", "300 diputados."], "bloque": "t3-composicion", "precepto": "Artículo 68.1 CE", "correcta": 0, "justificaciones": ["Es esta. La Constitución da una horquilla: entre 300 y 400.", "No. 350 es el número que fija la ley electoral, no el mínimo constitucional.", "No. Ni 250 ni 350: la horquilla empieza en 300 y acaba en 400.", "No. La Constitución no cierra el número; lo deja a la ley dentro de la horquilla."], "arts": [68], "citas": [{"texto": "«El Congreso se compone de un mínimo de 300 y un máximo de 400 Diputados, elegidos por sufragio universal, libre, igual, directo y secreto, en los términos que establezca la ley.»", "fuente": "Artículo 68.1 CE"}], "marca": {"nivel": "clave", "nota": "Composición de las Cortes, el Congreso y el Senado: cifras que el INAP pregunta a menudo."}, "truco": "La Constitución da la horquilla (300-400), la LOREG pone el número (350). Si la opción da una cifra exacta, sospecha."}, {"id": "ce-166", "origen": "oficiales", "test": "INAP julio 2026 (extraordinario)", "n": 19, "enunciado": "Conforme al artículo 94.1 de la Constitución Española de 1978, requieren la autorización previa de Cortes Generales los tratados internacionales:", "opciones": ["Que contengan acuerdos de asociación con terceros países.", "Los tratados o convenios que versen sobre materias de competencia exclusiva del Estado.", "Los tratados o convenios que supongan modificación o derogación de normas reglamentarias.", "Los tratados o convenios que exijan medidas legislativas para su ejecución."], "bloque": "t3-tratados", "precepto": "Artículo 94.1 e) CE", "correcta": 3, "justificaciones": ["No. Los «acuerdos de asociación con terceros países» no son ninguna de las cinco letras del 94.1.", "No. La competencia exclusiva del Estado no aparece como causa en el 94.1.", "No. El 94.1 e) habla de modificar o derogar **una ley**. Si el tratado solo toca un reglamento, no hace falta autorización previa.", "Es esta. Es la letra e) del 94.1, literal."], "arts": [94], "citas": [{"texto": "«La prestación del consentimiento del Estado para obligarse por medio de tratados o convenios requerirá la previa autorización de las Cortes Generales, en los siguientes casos: […] e) Tratados o convenios que supongan modificación o derogación de alguna ley o exijan medidas legislativas para su ejecución.»", "fuente": "Artículo 94.1 e) CE"}], "marca": {"nivel": "clave", "nota": "Tratados internacionales: qué necesita autorización por ley orgánica y cuáles solo de las Cortes. Ha caído en el INAP."}, "truco": "Las cinco letras del 94.1, en orden y resumidas: político, militar, territorio o derechos del Título I, dinero, ley. Los demás tratados solo se comunican a las Cámaras (94.2)."}, {"id": "ce-171", "origen": "oficiales", "test": "INAP sept 2025", "n": 4, "enunciado": "De acuerdo con el artículo 71 de la Constitución Española de 1978, ¿quién será competente en las causas contra Diputados y Senadores?", "opciones": ["El Tribunal Constitucional.", "La Sala de lo Penal de la Audiencia Nacional.", "La Sala de lo Penal del Tribunal Supremo.", "La Sala de lo Contencioso-Administrativo del Tribunal Supremo."], "bloque": "t3-composicion", "precepto": "Artículo 71.3 CE", "correcta": 2, "justificaciones": ["No. El Tribunal Constitucional no juzga causas penales.", "No. La Audiencia Nacional no conoce de las causas contra parlamentarios.", "Es esta. Sala de lo Penal del Tribunal Supremo. Es el aforamiento de diputados y senadores.", "No. Es la Sala de lo Penal, no la de lo Contencioso-Administrativo."], "arts": [71], "citas": [{"texto": "«En las causas contra Diputados y Senadores será competente la Sala de lo Penal del Tribunal Supremo.»", "fuente": "Artículo 71.3 CE"}], "truco": "El 71 va en escalera: inviolabilidad por las opiniones (71.1), inmunidad con detención solo en flagrante delito y suplicatorio (71.2), y aforamiento ante la Sala de lo Penal del TS (71.3)."}, {"id": "ce-174", "origen": "oficiales", "test": "INAP sept 2025", "n": 18, "enunciado": "Según lo dispuesto en los artículos 90 y 91 de la Constitución Española de 1978, aprobado un proyecto de ley ordinaria u orgánica por el Congreso de los Diputados, su Presidente dará inmediata cuenta del mismo al Presidente del Senado, el cual lo someterá a la deliberación de éste. Indique la respuesta correcta:", "opciones": ["El Senado en el plazo de tres meses, a partir del día de la recepción del texto, puede, mediante mensaje motivado, oponer su veto o introducir enmiendas al mismo.", "El proyecto no podrá ser sometido al Rey para sanción sin que el Congreso ratifique por mayoría absoluta, una vez transcurrido el plazo previsto en el artículo 91 de la Constitución Española de 1978 desde la interposición del mismo.", "El plazo de dos meses de que el Senado dispone para vetar o enmendar el proyecto se reducirá al de veinte días naturales en los proyectos declarados urgentes por el Gobierno o por el Congreso de los Diputados.", "El Rey sancionará en el plazo de veinte días naturales las leyes aprobadas por las Cortes Generales, y las promulgará y ordenará su inmediata publicación."], "bloque": "t3-leyes", "precepto": "Artículo 90.3 CE", "correcta": 2, "justificaciones": ["No. El plazo ordinario del Senado es de **dos** meses, no de tres.", "No. Pasados los dos meses, al Congreso le basta la mayoría **simple**. La absoluta solo se exige para levantar un veto.", "Es esta. Veinte días naturales cuando el proyecto se declara urgente, y puede declararlo el Gobierno o el Congreso.", "No. El Rey sanciona en el plazo de **quince** días (artículo 91), no de veinte."], "arts": [90], "citas": [{"texto": "«El plazo de dos meses de que el Senado dispone para vetar o enmendar el proyecto se reducirá al de veinte días naturales en los proyectos declarados urgentes por el Gobierno o por el Congreso de los Diputados.»", "fuente": "Artículo 90.3 CE"}], "truco": "Los números del trámite: 2 meses el Senado · 20 días naturales si urge · mayoría absoluta contra el veto · simple pasados los 2 meses · 15 días para la sanción del Rey."}, {"id": "ce-178", "origen": "oficiales", "test": "INAP 2025 (extraordinario)", "n": 3, "enunciado": "Según el artículo 67 de la Constitución Española de 1978:", "opciones": ["Nadie podrá ser miembro de las dos Cámaras simultáneamente, ni acumular el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso.", "Nadie podrá ser miembro de las dos Cámaras simultáneamente, excepto el Presidente del Gobierno y los Presidentes Autonómicos, ni acumular el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso.", "Nadie podrá ser miembro de las dos Cámaras simultáneamente, pero si es posible acumular el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso.", "Nadie podrá ser miembro de las dos Cámaras simultáneamente, salvo los miembros del Gobierno, ni acumular el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso."], "bloque": "t3-composicion", "precepto": "Artículo 67.1 CE", "correcta": 0, "justificaciones": ["Es esta. Reproduce el 67.1 entero: las dos prohibiciones y ninguna excepción.", "No. Ni el Presidente del Gobierno ni los presidentes autonómicos están exceptuados.", "No. El acta autonómica tampoco puede acumularse con la de Diputado: es la segunda prohibición del artículo.", "No. Los miembros del Gobierno no tienen excepción alguna aquí."], "arts": [67], "citas": [{"texto": "«Nadie podrá ser miembro de las dos Cámaras simultáneamente, ni acumular el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso.»", "fuente": "Artículo 67.1 CE"}], "truco": "Este mismo artículo volvió a caer en mayo de 2026, y allí la respuesta buena era la versión corta del 67.1. El precepto es el mismo; lo que cambia es dónde meten el añadido falso. Aprende el artículo, no la frase."}, {"id": "ce-179", "origen": "oficiales", "test": "INAP 2025 (extraordinario)", "n": 4, "enunciado": "Según el artículo 69.4 de la Constitución Española de 1978:", "opciones": ["Las poblaciones de Ceuta y Melilla elegirán cada una de ellas tres Senadores.", "Las poblaciones de Ceuta y Melilla elegirán cada una de ellas dos Senadores.", "Las poblaciones de Ceuta y Melilla no tienen representación en el Senado.", "Las poblaciones de Ceuta y Melilla elegirán cada una de ellas un Senador."], "bloque": "t3-composicion", "precepto": "Artículo 69.4 CE", "correcta": 1, "justificaciones": ["No. Tres son los que corresponden a cada una de las islas mayores (Gran Canaria, Mallorca y Tenerife) en el 69.3.", "Es esta. Dos Senadores cada una.", "No. Sí tienen representación en el Senado: dos senadores cada una.", "No. Uno es lo que eligen las islas menores, y también el número de Diputados de Ceuta y Melilla en el Congreso."], "arts": [69], "citas": [{"texto": "«Las poblaciones de Ceuta y Melilla elegirán cada una de ellas dos Senadores.»", "fuente": "Artículo 69.4 CE"}], "marca": {"nivel": "clave", "nota": "Composición de las Cortes, el Congreso y el Senado: cifras que el INAP pregunta a menudo."}, "truco": "El número baila entre Cámaras: Ceuta y Melilla eligen **1 Diputado** cada una (68.2) y **2 Senadores** (69.4). Y ojo, el 69.3 se reformó el 19 de mayo de 2026 para dar circunscripción propia a Ibiza y Formentera; el apartado 4 no se tocó."}, {"id": "ce-183", "origen": "oficiales", "test": "INAP 2025 (extraordinario)", "n": 17, "enunciado": "Según la Constitución Española de 1978, señale la respuesta correcta en relación con la elaboración de las leyes:", "opciones": ["La aprobación, modificación o derogación de las leyes orgánicas exigirá mayoría absoluta de las Cortes, en una votación final sobre el conjunto del proyecto.", "La iniciativa legislativa corresponde al Gobierno y al Congreso, de acuerdo con la Constitución.", "La delegación legislativa deberá otorgarse mediante una ley orgánica cuando su objeto sea la formación de textos articulados o por una ley ordinaria cuando se trate de refundir varios textos legales en uno solo.", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas, excepto las relativas al desarrollo de los derechos fundamentales y de las libertades públicas, las que aprueben los Estatutos de Autonomía y el régimen lectoral general y las demás previstas en la Constitución."], "bloque": "t3-leyes", "precepto": "Artículo 82.1 CE, con la lista del 81.1", "correcta": 3, "justificaciones": ["No. La mayoría absoluta de las leyes orgánicas es la del **Congreso** (81.2), no la de «las Cortes».", "No. La iniciativa legislativa corresponde al Gobierno, al Congreso **y al Senado** (87.1). Falta una Cámara.", "No. Está del revés: ley de bases para formar textos articulados y ley ordinaria para refundir (82.2).", "Es esta. El «artículo anterior» al que remite el 82.1 es el 81.1, el de las leyes orgánicas: desarrollo de derechos fundamentales y libertades públicas, Estatutos de Autonomía, régimen electoral general y las demás previstas en la Constitución. Justo lo que enumera la opción."], "arts": [81, 82], "citas": [{"texto": "«Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas no incluidas en el artículo anterior.»", "fuente": "Artículo 82.1 CE, con la lista del 81.1"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}, "truco": "Lo que no se puede delegar es lo que exige ley orgánica. Y el binomio del 82.2: bases → texto articulado; ordinaria → refundido."}, {"id": "ce-186", "origen": "oficiales", "test": "INAP sept 2023", "n": 8, "enunciado": "De acuerdo con el artículo 75 de la Constitución Española de 1978 (en adelante CE), ¿qué proyectos o proposiciones de ley NO podrán ser objeto de delegación de las Cámaras para su aprobación en las Comisiones Legislativas Permanentes?", "opciones": ["Las leyes de contenido económico.", "Las leyes que modifiquen leyes ya aprobadas y en vigor.", "Las leyes de bases.", "Las leyes que supongan la imposición directa de obligaciones a los ciudadanos."], "bloque": "t3-composicion", "precepto": "Artículo 75.3 CE", "correcta": 2, "justificaciones": ["No. «Leyes de contenido económico» no es la fórmula: lo excluido son los Presupuestos Generales del Estado.", "No. Modificar una ley en vigor no impide la delegación.", "Es esta. Las leyes de bases están en la lista de lo que no se puede delegar en las Comisiones.", "No. Imponer obligaciones a los ciudadanos tampoco figura entre las excepciones."], "arts": [75], "citas": [{"texto": "«Quedan exceptuados de lo dispuesto en el apartado anterior la reforma constitucional, las cuestiones internacionales, las leyes orgánicas y de bases y los Presupuestos Generales del Estado.»", "fuente": "Artículo 75.3 CE"}], "truco": "Cuatro excepciones y todas son «materia grave»: reforma constitucional, cuestiones internacionales, leyes orgánicas y de bases, y Presupuestos."}, {"id": "ce-187", "origen": "oficiales", "test": "INAP sept 2023", "n": 19, "enunciado": "Según el artículo 86 de la CE, los Decretos-leyes dictados por el Gobierno NO podrán afectar a:", "opciones": ["El ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni al Derecho electoral general.", "Los derechos y deberes de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas, al Derecho electoral general ni a la legislación presupuestaria.", "Los derechos, deberes y libertades de los ciudadanos regulados en el Título II, al régimen de las Comunidades Autónomas ni al Derecho electoral general.", "El ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título II, al régimen de las Comunidades Autónomas ni al Derecho electoral general."], "bloque": "t3-leyes", "precepto": "Artículo 86.1 CE", "correcta": 0, "justificaciones": ["Es esta. Los cuatro límites completos y con el Título correcto, el I.", "No. Se come «el ordenamiento de las instituciones básicas del Estado» y añade la legislación presupuestaria, que no es un límite del 86.1.", "No. Dice Título **II** (que es el de la Corona) y además omite las instituciones básicas.", "No. Mantiene los cuatro límites, pero cambia el Título I por el Título II."], "arts": [86], "citas": [{"texto": "«En caso de extraordinaria y urgente necesidad, el Gobierno podrá dictar disposiciones legislativas provisionales que tomarán la forma de Decretos-leyes y que no podrán afectar al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni al Derecho electoral general.»", "fuente": "Artículo 86.1 CE"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}, "truco": "Cuatro límites, en este orden: instituciones básicas · Título I · Comunidades Autónomas · Derecho electoral general. El Título es siempre el I, el de los derechos."}, {"id": "ce-192", "origen": "oficiales", "test": "INAP dic 2023", "n": 8, "enunciado": "Según la Constitución Española, señale la respuesta CORRECTA en relación con la elaboración de las leyes:", "opciones": ["La aprobación, modificación o derogación de las leyes orgánicas exigirá mayoría absoluta de las Cortes, en una votación final sobre el conjunto del proyecto.", "La iniciativa legislativa corresponde al Gobierno y al Congreso, de acuerdo con la Constitución y el Reglamento de dicha Cámara.", "La delegación legislativa podrá otorgarse al Gobierno de forma expresa para materia concreta correspondiendo al Consejo de Ministros la fijación del plazo para su ejercicio.", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas, excepto las relativas al desarrollo de los derechos fundamentales y de las libertades públicas, las que aprueben los Estatutos de Autonomía y el régimen electoral general y las demás previstas en la Constitución."], "bloque": "t3-leyes", "precepto": "Artículo 82.1 CE, con la lista del 81.1", "correcta": 3, "justificaciones": ["No. La mayoría absoluta que exige el 81.2 es la del **Congreso**.", "No. La iniciativa legislativa es del Gobierno, del Congreso y del **Senado** (87.1).", "No. El plazo lo fija la propia ley de delegación, no el Consejo de Ministros: el 82.3 exige delegación expresa, para materia concreta y con plazo.", "Es esta. Otra vez el 82.1 leído junto al 81.1: no cabe delegar lo que es materia de ley orgánica."], "arts": [81, 82], "citas": [{"texto": "«Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas no incluidas en el artículo anterior.»", "fuente": "Artículo 82.1 CE, con la lista del 81.1"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}, "truco": "Esta pregunta cayó dos veces casi igual, en diciembre de 2023 y en el extraordinario de 2025, y la opción buena es la misma: la transcripción del 82.1 con la lista del 81.1. Cuando veas una opción larguísima que parece copiada del BOE, suele serlo."}, {"id": "ce-194", "origen": "oficiales", "test": "INAP dic 2023", "n": 16, "enunciado": "De acuerdo con el artículo 78 de la Constitución, expirado el mandato de las Cortes Generales o en caso de disolución de las mismas, las Diputaciones Permanentes seguirán ejerciendo sus funciones hasta:", "opciones": ["La celebración de las elecciones.", "La proclamación de los resultados electorales definitivos.", "La elección de los nuevos presidentes de cada una de las Cámaras de las Cortes Generales.", "La constitución de las nuevas Cortes Generales."], "bloque": "t3-composicion", "precepto": "Artículo 78.3 CE", "correcta": 3, "justificaciones": ["No. La celebración de las elecciones no basta: entre las elecciones y la constitución de las Cámaras hay semanas en las que alguien tiene que velar por los poderes.", "No. La proclamación de resultados tampoco es el hito.", "No. Los nuevos Presidentes se eligen ya en la sesión constitutiva, que es precisamente el momento en que cesa la Diputación Permanente.", "Es esta. Hasta que se constituyen las nuevas Cortes: ni las elecciones ni la proclamación de resultados cierran el mandato de la Diputación Permanente."], "arts": [78], "citas": [{"texto": "«Expirado el mandato o en caso de disolución, las Diputaciones Permanentes seguirán ejerciendo sus funciones hasta la constitución de las nuevas Cortes Generales.»", "fuente": "Artículo 78.3 CE"}], "truco": "La Diputación Permanente es el «Parlamento de guardia»: mínimo veintiún miembros (78.1), asume las facultades de la Cámara para decretos-leyes y estados excepcionales (78.2) y dura hasta que se constituyen las nuevas Cortes (78.3)."}, {"id": "ce-195", "origen": "oficiales", "test": "INAP dic 2023", "n": 19, "enunciado": "En relación al funcionamiento de las Cortes Generales recogido en el Título III de la Constitución, señala la respuesta CORRECTA:", "opciones": ["En cada Cámara habrá una Diputación Permanente compuesta por un mínimo de veinticinco miembros.", "El voto de Senadores y Diputados es personal e indelegable.", "Las Cámaras funcionarán en Pleno, Comisiones y Salas.", "Las Cámaras podrán reunirse en sesiones extraordinarias a petición del Gobierno, de la Diputación Permanente o por mayoría de tres quintos de cualquiera de las Cámaras."], "bloque": "t3-composicion", "precepto": "Artículo 79.3 CE", "correcta": 1, "justificaciones": ["No. La Diputación Permanente tiene un mínimo de **veintiún** miembros (78.1), no veinticinco.", "Es esta. Personal e indelegable, en cuatro palabras.", "No. Las Cámaras funcionan en Pleno y por Comisiones (75.1). «Salas» son de los tribunales.", "No. Las sesiones extraordinarias se piden a instancia del Gobierno, de la Diputación Permanente o de la **mayoría absoluta** de los miembros de cualquiera de las Cámaras (73.2), no por tres quintos."], "arts": [79], "citas": [{"texto": "«El voto de Senadores y Diputados es personal e indelegable.»", "fuente": "Artículo 79.3 CE"}], "truco": "Los números del Título III que más caen: 21 miembros la Diputación Permanente · Pleno y Comisiones · mayoría absoluta para pedir sesión extraordinaria · dos períodos de sesiones, septiembre-diciembre y febrero-junio."}, {"id": "ce-201", "origen": "oficiales", "test": "INAP feb 2022 (estabilización)", "n": 1, "enunciado": "De acuerdo con la Constitución Española (en adelante CE), señale el tipo de norma mediante la cual se podrá autorizar la celebración de tratados por los que se atribuya a una organización o institución internacional el ejercicio de competencias derivadas de la Constitución:", "opciones": ["Ley orgánica.", "Ley ordinaria.", "Ley de transferencia.", "Ley de armonización."], "bloque": "t3-tratados", "precepto": "Artículo 93 CE", "correcta": 0, "justificaciones": ["Es esta. Ley orgánica. Es el artículo por el que España entró en las Comunidades Europeas.", "No. La ley ordinaria no sirve para ceder competencias derivadas de la Constitución.", "No. Las leyes de transferencia o delegación son las del 150.2 y sirven para pasar competencias estatales a las Comunidades Autónomas.", "No. Las leyes de armonización son las del 150.3 y tampoco tienen que ver con los tratados."], "arts": [93], "citas": [{"texto": "«Mediante ley orgánica se podrá autorizar la celebración de tratados por los que se atribuya a una organización o institución internacional el ejercicio de competencias derivadas de la Constitución.»", "fuente": "Artículo 93 CE"}], "marca": {"nivel": "clave", "nota": "Tratados internacionales: qué necesita autorización por ley orgánica y cuáles solo de las Cortes. Ha caído en el INAP."}, "truco": "Tres artículos seguidos y tres cosas distintas: el 93 cede competencias hacia arriba (ley orgánica), el 94 exige autorización de las Cortes para ciertos tratados, y el 96 dice que los tratados válidamente celebrados forman parte del ordenamiento interno."}, {"id": "ce-202", "origen": "oficiales", "test": "INAP feb 2022 (estabilización)", "n": 2, "enunciado": "Según el artículo 86 de la CE, señale quién debe convalidar o derogar un Decreto-Ley en el plazo de los treinta días siguientes a su promulgación:", "opciones": ["El Senado.", "El Congreso.", "Las Cortes Generales.", "El Tribunal Constitucional."], "bloque": "t3-leyes", "precepto": "Artículo 86.2 CE", "correcta": 1, "justificaciones": ["No. El Senado no interviene en la convalidación.", "Es esta. El Congreso, y solo el Congreso.", "No. «Las Cortes Generales» es la trampa habitual: el 86.2 nombra únicamente al Congreso de los Diputados.", "No. El Tribunal Constitucional no convalida decretos-leyes; podrá controlarlos después."], "arts": [86], "citas": [{"texto": "«Los Decretos-leyes deberán ser inmediatamente sometidos a debate y votación de totalidad al Congreso de los Diputados, convocado al efecto si no estuviere reunido, en el plazo de los treinta días siguientes a su promulgación. El Congreso habrá de pronunciarse expresamente dentro de dicho plazo sobre su convalidación o derogación…»", "fuente": "Artículo 86.2 CE"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}, "truco": "Convalida el Congreso en 30 días. Las Cortes solo aparecen en el 86.3, cuando el decreto-ley se tramita además como proyecto de ley por el procedimiento de urgencia."}, {"id": "ce-203", "origen": "oficiales", "test": "INAP mar 2022 (estabilización)", "n": 1, "enunciado": "Según el artículo 86 de la Constitución (en adelante CE), los Decretos-leyes deberán ser inmediatamente sometidos a debate y votación de la totalidad al Congreso de los Diputados, convocado al efecto si no estuviere reunido, en el plazo de:", "opciones": ["Los 30 días siguientes a su promulgación.", "Los 20 días siguientes a su promulgación.", "Los 30 días siguientes a su entrada en vigor.", "Los 20 días siguientes a su entrada en vigor."], "bloque": "t3-leyes", "precepto": "Artículo 86.2 CE", "correcta": 0, "justificaciones": ["Es esta. Treinta días, y contados desde la promulgación.", "No. Veinte días no es el plazo del 86.2.", "No. El plazo es correcto, pero el cómputo arranca en la **promulgación**, no en la entrada en vigor.", "No. Se equivoca en las dos cosas: ni veinte días ni entrada en vigor."], "arts": [86], "citas": [{"texto": "«…en el plazo de los treinta días siguientes a su promulgación.»", "fuente": "Artículo 86.2 CE"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}, "truco": "Dos datos y los dos importan: **30 días** y **desde la promulgación**. Las opciones falsas suelen cambiar solo el segundo, que es el que se olvida."}, {"id": "ce-204", "origen": "oficiales", "test": "INAP mar 2022 (estabilización)", "n": 5, "enunciado": "Según el artículo 86.1 de la CE, los Decretos-leyes no podrán afectar:", "opciones": ["Al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni al Régimen de la Seguridad Social.", "Al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni a la regulación de la jurisdicción contencioso-administrativa.", "Al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni a la vigencia del Documento Nacional de Identidad.", "Al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni al Derecho electoral general."], "bloque": "t3-leyes", "precepto": "Artículo 86.1 CE", "correcta": 3, "justificaciones": ["No. Cambia el Derecho electoral general por el régimen de la Seguridad Social.", "No. Lo cambia por la jurisdicción contencioso-administrativa.", "No. Lo cambia por la vigencia del Documento Nacional de Identidad.", "Es esta. El cuarto límite es el Derecho electoral general."], "arts": [86], "citas": [{"texto": "«…no podrán afectar al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni al Derecho electoral general.»", "fuente": "Artículo 86.1 CE"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}, "truco": "Los tres primeros límites se repiten intactos en todas las opciones: la pregunta se juega entera en el cuarto. Apréndelo suelto: **Derecho electoral general**."}, {"id": "ce-205", "origen": "otras", "test": "Test Tema 3", "n": 8, "enunciado": "De acuerdo con el artículo 22 del Reglamento del Congreso de los Diputados, NO es causa de la pérdida de la condición de Diputado:", "opciones": ["La existencia de una decisión judicial firme que anule la elección o la proclamación del Diputado.", "La renuncia del Diputado ante la Mesa del Congreso.", "La declaración judicial de persona investigada.", "El fallecimiento o incapacitación del Diputado, declarada esta por decisión judicial firme."], "bloque": "t3-control", "precepto": "Artículo 22.1 · Reglamento del Congreso de los Diputados", "correcta": 2, "justificaciones": ["No. Sí es causa expresa del artículo 22.1: la decisión judicial firme que anula la elección o la proclamación.", "No. Sí es causa: la renuncia del propio Diputado ante la Mesa.", "Es esta. La pérdida del escaño exige siempre un hecho consumado y firme (una sentencia firme, una renuncia, el fallecimiento), nunca la mera apertura de una investigación, que no prejuzga nada y respeta la presunción de inocencia.", "No. Sí es causa: el fallecimiento o la incapacitación declarada por decisión judicial firme."], "arts": [], "citas": [{"texto": "«Son causas de pérdida de la condición de Diputado: la decisión judicial firme que anule la elección o proclamación; el fallecimiento o incapacitación declarada por decisión judicial firme; la renuncia ante la Mesa del Congreso; la extinción del partido o federación por el que concurrió, y la pérdida de la condición de español.»", "fuente": "Artículo 22.1 · Reglamento del Congreso de los Diputados"}], "marca": {"nivel": "poco", "nota": "El Reglamento del Congreso apenas sale: una pregunta de academia en todo el banco."}, "truco": "Investigado no es condenado. Mientras no haya sentencia firme, el escaño se mantiene: es la presunción de inocencia trasladada al Reglamento del Congreso."}, {"id": "ce-206", "origen": "otras", "test": "Test Tema 3", "n": 9, "enunciado": "Según el artículo 78 de la CE, la composición de la Diputación Permanente de cada una de las Cámaras estará integrada por un mínimo de:", "opciones": ["Quince miembros.", "Dieciocho miembros.", "Veintiún miembros.", "Veinticinco miembros."], "bloque": "t3-composicion", "precepto": "Artículo 78.1 CE", "correcta": 2, "justificaciones": ["No. Quince no es la cifra del precepto.", "No. Dieciocho tampoco.", "Es esta. Literal del 78.1: un mínimo de veintiún miembros.", "No. Veinticinco tampoco: el mínimo constitucional es veintiuno."], "arts": [78], "citas": [{"texto": "«En cada Cámara habrá una Diputación Permanente compuesta por un mínimo de veintiún miembros, que representarán a los grupos parlamentarios, en proporción a su importancia numérica.»", "fuente": "Artículo 78.1 CE"}], "truco": "Diputación Permanente: mínimo 21 miembros, uno por cada Cámara. No la confundas con la Comisión Mixta de reforma constitucional, que es de composición paritaria sin cifra fija."}, {"id": "ce-207", "origen": "otras", "test": "Test Tema 3", "n": 10, "enunciado": "De acuerdo con la Constitución Española, los Senadores que se eligen por sufragio universal, libre, igual, directo y secreto por los votantes de cada provincia son:", "opciones": ["Uno.", "Cuatro.", "Tres.", "Dos."], "bloque": "t3-composicion", "precepto": "Artículo 69.2 CE", "correcta": 1, "justificaciones": ["No. Uno es la cifra de las islas menores (69.3), no de las provincias.", "Es esta. Literal del 69.2: cuatro Senadores por provincia.", "No. Tres es la cifra de las islas mayores (69.3).", "No. Dos es la cifra de Ceuta y Melilla (69.4)."], "arts": [69], "citas": [{"texto": "«En cada provincia se elegirán cuatro Senadores por sufragio universal, libre, igual, directo y secreto por los votantes de cada una de ellas, en los términos que señale una ley orgánica.»", "fuente": "Artículo 69.2 CE"}], "marca": {"nivel": "clave", "nota": "Composición de las Cortes, el Congreso y el Senado: cifras que el INAP pregunta a menudo."}, "truco": "El artículo 69 reparte cifras distintas según el territorio: 4 por provincia, 3 por isla mayor, 1 por isla menor, 2 por Ceuta y Melilla, y 1+1/millón por Comunidad Autónoma."}, {"id": "ce-208", "origen": "otras", "test": "Test Tema 3", "n": 11, "enunciado": "De conformidad con el artículo 74.2 de la CE, la prestación del consentimiento del Estado para obligarse por medio de los tratados a que se refiere el artículo 94.1 requerirá la previa autorización de las Cortes Generales, que se adoptará:", "opciones": ["Por mayoría de cada una de las Cámaras, iniciando el procedimiento el Congreso.", "Por mayoría de cada una de las Cámaras, iniciando el procedimiento el Senado.", "Por mayoría del Congreso, iniciando el procedimiento el Congreso.", "Por mayoría del Congreso, iniciando el procedimiento el Presidente del Gobierno."], "bloque": "t3-composicion", "precepto": "Artículo 74.2 CE", "correcta": 0, "justificaciones": ["Es esta. Los tratados del artículo 94.1 son el «primer caso» de la lista del 74.2: mayoría de cada Cámara e inicio en el Congreso.", "No. El Senado inicia el procedimiento en los otros dos supuestos del 74.2 (arts. 145.2 y 158.2), no en el de los tratados.", "No. No basta la mayoría del Congreso solo: hace falta la mayoría de cada una de las Cámaras.", "No. El Presidente del Gobierno no inicia este procedimiento parlamentario."], "arts": [74], "citas": [{"texto": "«Las decisiones de las Cortes Generales previstas en los artículos 94, 1, 145, 2 y 158, 2, se adoptarán por mayoría de cada una de las Cámaras. En el primer caso, el procedimiento se iniciará por el Congreso, y en los otros dos, por el Senado.»", "fuente": "Artículo 74.2 CE"}]}, {"id": "ce-209", "origen": "otras", "test": "Test Tema 3", "n": 12, "enunciado": "De acuerdo con el artículo 68 de la CE, el Congreso:", "opciones": ["Está formado por 350 diputados.", "La elección de sus miembros se verificará en cada circunscripción atendiendo a criterios de representación mayoritaria.", "Serán electores y elegibles los españoles y extranjeros mayores de edad, según lo que dispongan los tratados internacionales en atención a criterios de reciprocidad.", "El mandato de los Diputados termina cuatro años después de su elección o el día de la disolución de la Cámara."], "bloque": "t3-composicion", "precepto": "Artículo 68.1 y 68.4 CE", "correcta": 3, "justificaciones": ["No. La Constitución no fija 350: solo marca una horquilla de 300 a 400 (68.1); los 350 los fija la ley electoral ordinaria, no el texto constitucional.", "No. La elección se verifica atendiendo a criterios de representación proporcional (68.3), no mayoritaria.", "No. El 68.5 habla solo de «todos los españoles»: los extranjeros no son electores ni elegibles al Congreso.", "Es esta. Literal del 68.4."], "arts": [68], "citas": [{"texto": "«El Congreso se compone de un mínimo de 300 y un máximo de 400 Diputados... El Congreso es elegido por cuatro años. El mandato de los Diputados termina cuatro años después de su elección o el día de la disolución de la Cámara.»", "fuente": "Artículo 68.1 y 68.4 CE"}], "marca": {"nivel": "clave", "nota": "Composición de las Cortes, el Congreso y el Senado: cifras que el INAP pregunta a menudo."}}, {"id": "ce-210", "origen": "otras", "test": "Test Tema 3", "n": 13, "enunciado": "Según lo previsto en el artículo 69 de la CE, las Comunidades Autónomas elegirán:", "opciones": ["Dos Senadores, y otro más por cada millón de habitantes de su respectivo territorio.", "Dos Senadores.", "Un Senador, y otro más por cada millón de habitantes de su respectivo territorio.", "Un Senador, y dos más por cada millón de habitantes de su respectivo territorio."], "bloque": "t3-composicion", "precepto": "Artículo 69.5 CE", "correcta": 2, "justificaciones": ["No. El precepto no habla de dos Senadores de partida.", "No. Falta la parte proporcional por millón de habitantes.", "Es esta. Literal del 69.5: un Senador, y otro más por cada millón de habitantes.", "No. El añadido por millón de habitantes es de uno, no de dos."], "arts": [69], "citas": [{"texto": "«Las Comunidades Autónomas designarán además un Senador y otro más por cada millón de habitantes de su respectivo territorio.»", "fuente": "Artículo 69.5 CE"}], "marca": {"nivel": "clave", "nota": "Composición de las Cortes, el Congreso y el Senado: cifras que el INAP pregunta a menudo."}}, {"id": "ce-211", "origen": "otras", "test": "Test Tema 3", "n": 14, "enunciado": "Según establece la CE en su artículo 71.2, para inculpar o procesar a Diputados o Senadores durante su mandato será necesaria una autorización previa que deberá emitir:", "opciones": ["El Tribunal Constitucional.", "El Congreso o el Senado, respectivamente.", "El Tribunal Supremo.", "El Rey, a propuesta del Presidente del Gobierno."], "bloque": "t3-composicion", "precepto": "Artículo 71.2 CE", "correcta": 1, "justificaciones": ["No. El Tribunal Constitucional no interviene en la inmunidad parlamentaria.", "Es esta. La autorización la da «la Cámara respectiva»: el Congreso si es Diputado, el Senado si es Senador.", "No. El Tribunal Supremo es quien juzga después (71.3, Sala de lo Penal), pero la autorización previa la da la Cámara.", "No. El Rey no interviene en este procedimiento."], "arts": [71], "citas": [{"texto": "«Durante el período de su mandato los Diputados y Senadores gozarán asimismo de inmunidad y sólo podrán ser detenidos en caso de flagrante delito. No podrán ser inculpados ni procesados sin la previa autorización de la Cámara respectiva.»", "fuente": "Artículo 71.2 CE"}]}, {"id": "ce-212", "origen": "otras", "test": "Test Tema 3", "n": 15, "enunciado": "De acuerdo con la Constitución Española, ¿cuántos Senadores eligen las poblaciones de Ceuta y Melilla?", "opciones": ["Ceuta y Melilla no eligen Senadores.", "4 Senadores cada una.", "1 Senador cada una.", "2 Senadores cada una."], "bloque": "t3-composicion", "precepto": "Artículo 69.4 CE", "correcta": 3, "justificaciones": ["No. Sí eligen Senadores, dos cada una.", "No. Cuatro es la cifra de las provincias (69.2), no la de Ceuta y Melilla.", "No. Uno es la cifra de las islas menores (69.3).", "Es esta. Literal del 69.4: dos Senadores cada una."], "arts": [69], "citas": [{"texto": "«Las poblaciones de Ceuta y Melilla elegirán cada una de ellas dos Senadores.»", "fuente": "Artículo 69.4 CE"}], "marca": {"nivel": "clave", "nota": "Composición de las Cortes, el Congreso y el Senado: cifras que el INAP pregunta a menudo."}}, {"id": "ce-213", "origen": "otras", "test": "Test Tema 3", "n": 17, "enunciado": "Entre las causas de inelegibilidad e incompatibilidad de los Diputados y Senadores que enumera el artículo 70.1 de la CE, NO se incluye:", "opciones": ["A los componentes del Tribunal Constitucional.", "Al Defensor del Pueblo.", "A los miembros del Gobierno.", "A los militares profesionales y miembros de las Fuerzas y Cuerpos de Seguridad y Policía en activo."], "bloque": "t3-composicion", "precepto": "Artículo 70.1 CE", "correcta": 2, "justificaciones": ["No. Sí está en la lista, letra a).", "No. Sí está en la lista, letra c).", "Es esta. El propio precepto excepciona expresamente a los miembros del Gobierno de la incompatibilidad de los altos cargos: por eso los ministros sí pueden ser también Diputados o Senadores.", "No. Sí está en la lista, letra e)."], "arts": [70], "citas": [{"texto": "«La ley electoral determinará las causas de inelegibilidad e incompatibilidad de los Diputados y Senadores, que comprenderán, en todo caso: a) A los componentes del Tribunal Constitucional. b) A los altos cargos de la Administración del Estado que determine la ley, con la excepción de los miembros del Gobierno. c) Al Defensor del Pueblo. d) A los Magistrados, Jueces y Fiscales en activo. e) A los militares profesionales y miembros de las Fuerzas y Cuerpos de Seguridad y Policía en activo. f) A los miembros de las Juntas Electorales.»", "fuente": "Artículo 70.1 CE"}], "truco": "El artículo 70.1.b) excepciona expresamente «con la excepción de los miembros del Gobierno»: es la única excepción de toda la lista, y por eso es la trampa favorita del examen."}, {"id": "ce-214", "origen": "otras", "test": "Test Tema 3", "n": 18, "enunciado": "Señale la respuesta correcta en relación con los representantes, tanto para el Congreso como para el Senado, elegidos por Ceuta y Melilla, según lo establecido en el Capítulo I del Título III de la Constitución Española:", "opciones": ["Estarán representadas cada una por dos diputados y dos senadores.", "Estarán representadas cada una por un diputado y dos senadores.", "Estarán representadas cada una por dos diputados y un senador.", "Estarán representadas cada una por dos senadores y el número de diputados que les corresponda atendiendo a criterios de representación proporcional."], "bloque": "t3-composicion", "precepto": "Artículo 68.2 CE · Artículo 69.4 CE", "correcta": 1, "justificaciones": ["No. Ceuta y Melilla no eligen dos Diputados cada una, sino uno.", "Es esta. Combinando los dos preceptos: un Diputado (68.2) más dos Senadores (69.4), cada una.", "No. El número de Senadores no es uno, sino dos.", "No. El número de Diputados de Ceuta y Melilla es fijo (uno cada una), no proporcional: el reparto proporcional del 68.2 es para el resto de circunscripciones."], "arts": [68, 69], "citas": [{"texto": "«Las poblaciones de Ceuta y Melilla estarán representadas cada una de ellas por un Diputado.»«Las poblaciones de Ceuta y Melilla elegirán cada una de ellas dos Senadores.»", "fuente": "Artículo 68.2 CE · Artículo 69.4 CE"}], "marca": {"nivel": "clave", "nota": "Composición de las Cortes, el Congreso y el Senado: cifras que el INAP pregunta a menudo."}}, {"id": "ce-215", "origen": "otras", "test": "Test Tema 3", "n": 19, "enunciado": "¿Cuál es la opción correcta según el artículo 99 de la Constitución Española de 1978?", "opciones": ["Si transcurrido el plazo de dos meses, a partir de la primera votación de investidura, ningún candidato hubiere obtenido la confianza del Congreso, el Rey disolverá ambas Cámaras y convocará nuevas elecciones con el refrendo del Presidente del Congreso.", "Si transcurrido el plazo de tres meses, a partir de la primera votación de investidura, ningún candidato hubiere obtenido la confianza del Congreso, el Rey disolverá ambas Cámaras y convocará nuevas elecciones con el refrendo del Presidente del Congreso.", "Si transcurrido el plazo de dos meses, a partir de la primera votación de investidura, ningún candidato hubiere obtenido la confianza del Senado, el Rey disolverá ambas Cámaras y convocará nuevas elecciones con el refrendo del Presidente del Congreso.", "Si transcurrido el plazo de tres meses, a partir de la primera votación de investidura, ningún candidato hubiere obtenido la confianza del Senado, el Rey disolverá ambas Cámaras y convocará nuevas elecciones con el refrendo del Presidente del Congreso."], "bloque": "t3-control", "precepto": "Artículo 99.5 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del 99.5: dos meses y confianza del Congreso, no del Senado.", "No. El plazo es de dos meses, no de tres.", "No. La confianza que se busca en la investidura es la del Congreso, no la del Senado.", "No. Combina los dos errores: ni tres meses ni Senado."], "arts": [99], "citas": [{"texto": "«Si transcurrido el plazo de dos meses, a partir de la primera votación de investidura, ningún candidato hubiere obtenido la confianza del Congreso, el Rey disolverá ambas Cámaras y convocará nuevas elecciones con el refrendo del Presidente del Congreso.»", "fuente": "Artículo 99.5 CE"}], "marca": {"nivel": "estrella", "nota": "La investidura del artículo 99 (plazos, mayorías y los dos meses) está en las listas y ha caído en el INAP."}, "truco": "La investidura y la posible disolución automática del artículo 99 giran siempre alrededor del Congreso, nunca del Senado. Y el reloj corre dos meses, no tres."}, {"id": "ce-216", "origen": "otras", "test": "Test Tema 3", "n": 20, "enunciado": "Según el artículo 75 de la Constitución Española de 1978, el Pleno de las Cámaras podrá:", "opciones": ["Delegar en las Diputaciones Permanentes la aprobación de proyectos o proposiciones de ley.", "Delegar la aprobación de proyectos de leyes de bases.", "Delegar la aprobación de proposiciones de ley sobre cuestiones internacionales.", "Recabar en cualquier momento la votación de cualquier proposición de ley que haya sido objeto de delegación."], "bloque": "t3-composicion", "precepto": "Artículo 75.2 y 75.3 CE", "correcta": 3, "justificaciones": ["No. La delegación es en las Comisiones Legislativas Permanentes, no en la Diputación Permanente, que es un órgano distinto.", "No. Las leyes de bases están expresamente excluidas de la delegación (75.3).", "No. Las cuestiones internacionales también están excluidas (75.3).", "Es esta. Literal del 75.2: el Pleno siempre puede recuperar para sí el debate y la votación de lo delegado."], "arts": [75], "citas": [{"texto": "«Las Cámaras podrán delegar en las Comisiones Legislativas Permanentes la aprobación de proyectos o proposiciones de ley. El Pleno podrá, no obstante, recabar en cualquier momento el debate y votación de cualquier proyecto o proposición de ley que haya sido objeto de esta delegación. Quedan exceptuados de lo dispuesto en el apartado anterior la reforma constitucional, las cuestiones internacionales, las leyes orgánicas y de bases y los Presupuestos Generales del Estado.»", "fuente": "Artículo 75.2 y 75.3 CE"}]}, {"id": "ce-217", "origen": "otras", "test": "Test exámenes", "n": 113, "enunciado": "Según el artículo 81.1 de la Constitución Española, son Leyes Orgánicas las relativas:", "opciones": ["Al desarrollo de los derechos fundamentales y de las libertades públicas, las que aprueben los Estatutos de Autonomía y el régimen electoral general y las demás previstas en la Constitución.", "Al desarrollo de los derechos y deberes fundamentales, las que aprueban los Estatutos de Autonomía y el régimen electoral general y las demás previstas en la Constitución.", "Al desarrollo de los derechos fundamentales y de las libertades públicas, las relativas a la organización de los poderes del Estado y las demás previstas en la Constitución.", "Al desarrollo de los derechos fundamentales y de las libertades públicas, las que afecten al desarrollo de los valores constitucionales y al régimen electoral general y las demás previstas en la Constitución."], "bloque": "t3-leyes", "precepto": "Artículo 81.1 CE", "correcta": 0, "justificaciones": ["Es esta. Reproduce el 81.1 palabra por palabra: tres piezas exactas (derechos fundamentales, Estatutos de Autonomía, régimen electoral general) y la cláusula de cierre.", "No. Cambia «derechos fundamentales» por «derechos y deberes fundamentales», que es una categoría más amplia que la del precepto.", "No. «La organización de los poderes del Estado» no es la fórmula del 81.1; esa expresión no aparece en el texto.", "No. «El desarrollo de los valores constitucionales» tampoco es la fórmula del precepto."], "arts": [81], "citas": [{"texto": "«Son leyes orgánicas las relativas al desarrollo de los derechos fundamentales y de las libertades públicas, las que aprueben los Estatutos de Autonomía y el régimen electoral general y las demás previstas en la Constitución.»", "fuente": "Artículo 81.1 CE"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}}, {"id": "ce-218", "origen": "otras", "test": "Test exámenes", "n": 131, "enunciado": "Según la Constitución, son Leyes Orgánicas:", "opciones": ["Las relativas al desarrollo de los derechos fundamentales y de las libertades públicas.", "Las relativas a los bienes de dominio público y comunales.", "Las relativas a los tributos, impuestos y beneficios fiscales.", "Las relativas a la emisión de Deuda Pública."], "bloque": "t3-leyes", "precepto": "Artículo 81.1 CE", "correcta": 0, "justificaciones": ["Es esta. Es la primera de las materias reservadas a ley orgánica por el 81.1.", "No. Los bienes de dominio público y comunales son del Título VII, Economía y Hacienda (art.132): ley ordinaria.", "No. Los tributos son también del Título VII (art.133): ley ordinaria.", "No. La emisión de Deuda Pública es del artículo 135, Título VII: ley ordinaria, no orgánica."], "arts": [81], "citas": [{"texto": "«Son leyes orgánicas las relativas al desarrollo de los derechos fundamentales y de las libertades públicas...»", "fuente": "Artículo 81.1 CE"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}, "truco": "Todo lo que huele a Título VII (tributos, deuda, bienes públicos, Presupuestos) se regula por ley ordinaria. La reserva de ley orgánica es la lista corta y tasada del artículo 81.1."}, {"id": "ce-219", "origen": "otras", "test": "Examen Tema 3", "n": 17, "enunciado": "De conformidad con lo establecido en el artículo 86 de la Constitución Española, los Decretos-leyes:", "opciones": ["Se aprueban por el Gobierno, previa delegación del Congreso de los Diputados, en un plazo máximo de 30 días.", "Tienen el mismo rango jerárquico normativo que el Real Decreto del Consejo de Ministros.", "Deberán ser inmediatamente sometidos a debate y votación de totalidad al Congreso de los Diputados, convocado al efecto si no estuviere reunido, en el plazo de los treinta días siguientes a su promulgación.", "Se convalidan por el Congreso de los Diputados y por el Senado."], "bloque": "t3-leyes", "precepto": "Artículo 86.2 CE", "correcta": 2, "justificaciones": ["No. El Decreto-ley no necesita delegación previa de nadie: es iniciativa directa del Gobierno en caso de extraordinaria y urgente necesidad (86.1).", "No. Tiene rango de ley (por eso puede modificar leyes), no el rango reglamentario de un Real Decreto del Consejo de Ministros.", "Es esta. Literal del 86.2.", "No. La convalidación es solo del Congreso; el Senado no interviene en este trámite."], "arts": [86], "citas": [{"texto": "«Los Decretos-leyes deberán ser inmediatamente sometidos a debate y votación de totalidad al Congreso de los Diputados, convocado al efecto si no estuviere reunido, en el plazo de los treinta días siguientes a su promulgación. El Congreso habrá de pronunciarse expresamente dentro de dicho plazo sobre su convalidación o derogación, para lo cual el Reglamento establecerá un procedimiento especial y sumario.»", "fuente": "Artículo 86.2 CE"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}, "truco": "Decreto-ley: 30 días, y decide solo el Congreso (convalidación o derogación). El Senado queda fuera de este trámite concreto."}, {"id": "ce-220", "origen": "otras", "test": "Test exámenes", "n": 151, "enunciado": "Según el artículo 86.3 de la Constitución Española, durante el plazo de treinta días para su convalidación, los Decretos-leyes:", "opciones": ["Delimitarán con precisión el objeto y alcance de la delegación.", "Deberán ser sometidos a debate y votación de totalidad al Congreso y al Senado.", "El Congreso y el Senado habrán de pronunciarse conjuntamente sobre su convalidación o derogación.", "Podrán tramitarse por las Cortes como proyectos de ley por el procedimiento de urgencia."], "bloque": "t3-leyes", "precepto": "Artículo 86.3 CE", "correcta": 3, "justificaciones": ["No. Delimitar objeto y alcance es cosa de las leyes de bases (82.4), no de los decretos-leyes.", "No. El debate de totalidad del 86.2 es solo ante el Congreso.", "No. La convalidación o derogación la decide únicamente el Congreso, no conjuntamente con el Senado.", "Es esta. Literal del 86.3: además de la convalidación del Congreso (86.2), cabe convertir el Decreto-ley en proyecto de ley tramitado por las Cortes con procedimiento de urgencia."], "arts": [86], "citas": [{"texto": "«Durante el plazo establecido en el apartado anterior, las Cortes podrán tramitarlos como proyectos de ley por el procedimiento de urgencia.»", "fuente": "Artículo 86.3 CE"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}}, {"id": "ce-221", "origen": "otras", "test": "Test exámenes", "n": 115, "enunciado": "De acuerdo con la Constitución, la delegación legislativa que las Cortes Generales pueden otorgar al Gobierno deberá realizarse, cuando su objeto sea la formación de textos articulados, mediante:", "opciones": ["Ley de armonización.", "Ley ordinaria.", "Ley de transferencia.", "Ley de bases."], "bloque": "t3-leyes", "precepto": "Artículo 82.2 CE", "correcta": 3, "justificaciones": ["No. La ley de armonización es la del artículo 150.3, para armonizar disposiciones de las Comunidades Autónomas: nada que ver con la delegación legislativa.", "No. La ley ordinaria es el cauce para refundir textos, no para formar textos articulados.", "No. «Ley de transferencia» es la del artículo 150.2, para transferir competencias estatales a las Comunidades Autónomas.", "Es esta. Textos articulados → ley de bases; refundir textos → ley ordinaria: el 82.2 separa ambos casos con precisión."], "arts": [82], "citas": [{"texto": "«La delegación legislativa deberá otorgarse mediante una ley de bases cuando su objeto sea la formación de textos articulados o por una ley ordinaria cuando se trate de refundir varios textos legales en uno solo.»", "fuente": "Artículo 82.2 CE"}], "marca": {"nivel": "clave", "nota": "Legislación delegada e iniciativa legislativa (las 500.000 firmas): muy repetidos en los test y en el INAP."}}, {"id": "ce-222", "origen": "otras", "test": "Test exámenes", "n": 123, "enunciado": "De acuerdo con la Constitución Española, señale el tipo de norma mediante la cual se podrá autorizar la celebración de tratados por los que se atribuya a una organización o institución internacional el ejercicio de competencias derivadas de la Constitución:", "opciones": ["Ley orgánica.", "Ley ordinaria.", "Ley de transferencia.", "Ley de armonización."], "bloque": "t3-tratados", "precepto": "Artículo 93 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 93: es la puerta constitucional de la integración en organizaciones supranacionales, como la Unión Europea.", "No. La ley ordinaria no basta para ceder competencias derivadas de la Constitución.", "No. La ley de transferencia (150.2) es para transferir competencias del Estado a las Comunidades Autónomas, no a organizaciones internacionales.", "No. La ley de armonización (150.3) tampoco tiene que ver con la cesión de competencias a organismos internacionales."], "arts": [93], "citas": [{"texto": "«Mediante ley orgánica se podrá autorizar la celebración de tratados por los que se atribuya a una organización o institución internacional el ejercicio de competencias derivadas de la Constitución.»", "fuente": "Artículo 93 CE"}], "marca": {"nivel": "clave", "nota": "Tratados internacionales: qué necesita autorización por ley orgánica y cuáles solo de las Cortes. Ha caído en el INAP."}, "truco": "El artículo 93 es la vía constitucional de la integración europea: por eso exige ley orgánica, el escalón más alto por debajo de la propia reforma constitucional."}, {"id": "ce-223", "origen": "otras", "test": "Test exámenes", "n": 126, "enunciado": "La prestación del consentimiento del Estado para obligarse por medio de tratados o convenios en materia de carácter militar, según la CE, requerirá:", "opciones": ["La aprobación de una Ley Orgánica.", "La previa autorización de las Cortes Generales.", "La previa autorización del Ministerio de Defensa.", "El consentimiento conjunto del Ministerio de Defensa y de las Cortes Generales."], "bloque": "t3-tratados", "precepto": "Artículo 94.1 CE", "correcta": 1, "justificaciones": ["No. No se exige ley orgánica para estos tratados, sino autorización de las Cortes.", "Es esta. Los tratados militares están en la letra b) de la lista tasada del 94.1: requieren autorización previa de las Cortes Generales, no ley orgánica.", "No. El Ministerio de Defensa no autoriza tratados internacionales.", "No. No hay un consentimiento «conjunto»: es la autorización de las Cortes Generales."], "arts": [94], "citas": [{"texto": "«La prestación del consentimiento del Estado para obligarse por medio de tratados o convenios requerirá la previa autorización de las Cortes Generales, en los siguientes casos: a) Tratados de carácter político. b) Tratados o convenios de carácter militar.»", "fuente": "Artículo 94.1 CE"}], "marca": {"nivel": "clave", "nota": "Tratados internacionales: qué necesita autorización por ley orgánica y cuáles solo de las Cortes. Ha caído en el INAP."}}, {"id": "ce-224", "origen": "otras", "test": "Test exámenes", "n": 127, "enunciado": "Según el artículo 86.1 de la CE, los Decretos-leyes no podrán afectar:", "opciones": ["Al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni al Régimen de la Seguridad Social.", "Al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni a la regulación de la jurisdicción contencioso-administrativa.", "Al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni a la vigencia del Documento Nacional de Identidad.", "Al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni al Derecho electoral general."], "bloque": "t3-leyes", "precepto": "Artículo 86.1 CE", "correcta": 3, "justificaciones": ["No. La Seguridad Social no es la cuarta materia vedada del 86.1.", "No. La jurisdicción contencioso-administrativa tampoco lo es.", "No. El DNI tampoco aparece en el precepto.", "Es esta. La lista cerrada del 86.1 termina en «Derecho electoral general», no en la Seguridad Social, la jurisdicción contencioso-administrativa ni el DNI."], "arts": [86], "citas": [{"texto": "«En caso de extraordinaria y urgente necesidad, el Gobierno podrá dictar disposiciones legislativas provisionales que tomarán la forma de Decretos-leyes y que no podrán afectar al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni al Derecho electoral general.»", "fuente": "Artículo 86.1 CE"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}, "truco": "Las cuatro materias vedadas al Decreto-ley, de memoria: instituciones básicas del Estado · derechos del Título I · régimen de las Comunidades Autónomas · Derecho electoral general. Todo lo demás distrae."}, {"id": "ce-225", "origen": "otras", "test": "Test exámenes", "n": 133, "enunciado": "Los Decretos-leyes, según el límite que fija el artículo 86.1 de la CE, sí podrán afectar:", "opciones": ["A la protección social, económica y jurídica de la familia.", "Al régimen de las Comunidades Autónomas.", "Al Derecho electoral general.", "A la libertad ideológica, religiosa y de culto."], "bloque": "t3-leyes", "precepto": "Artículo 86.1 CE", "correcta": 0, "justificaciones": ["Es esta. La protección de la familia (art.39, principio rector del Capítulo III) no figura en la lista cerrada de materias vedadas del 86.1: por descarte, es la única de las cuatro opciones que el Decreto-ley sí puede tocar.", "No. El régimen de las Comunidades Autónomas es una de las cuatro materias expresamente vedadas.", "No. El Derecho electoral general también está vedado.", "No. La libertad ideológica, religiosa y de culto (art.16) es un derecho del Título I: vedada."], "arts": [86], "citas": [{"texto": "«...no podrán afectar al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni al Derecho electoral general.»", "fuente": "Artículo 86.1 CE"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}}, {"id": "ce-226", "origen": "otras", "test": "Test exámenes", "n": 128, "enunciado": "¿En qué se diferencia un decreto-ley de un decreto legislativo?", "opciones": ["En que el decreto legislativo no puede versar sobre materias reservadas a una ley orgánica y el decreto-ley sí.", "En que el decreto legislativo está previsto para redacción de textos articulados y el decreto-ley para refundir varios textos legales en uno solo.", "En que el decreto-ley necesita de una ley de bases que determine el alcance de la regulación que se le encomienda y el decreto legislativo tiene que estar previsto en una ley ordinaria.", "En que el decreto-ley es una disposición legislativa provisional que se dicta por el Gobierno en caso de extraordinaria y urgente necesidad; y el decreto legislativo es fruto de una delegación expresa de las Cortes Generales en el Gobierno para dictar normas con rango de ley sobre materias determinadas."], "bloque": "t3-leyes", "precepto": "Artículo 86.1 CE · Artículo 82.1 CE", "correcta": 3, "justificaciones": ["No. Ninguno de los dos puede versar sobre materias de ley orgánica: al decreto-ley se lo veda el 86.1 (derechos del Título I) y a la delegación legislativa el 82.1 («materias determinadas no incluidas en el artículo anterior», es decir, distintas de las del 81).", "No. Es justo al revés: la ley de bases es para textos articulados y la ley ordinaria de delegación es para refundir textos (82.2).", "No. El decreto-ley no necesita ninguna ley de bases; la ley de bases es el instrumento para delegar la formación de textos articulados (82.2), no para dictar decretos-leyes.", "Es esta. El decreto-ley nace de la urgencia y la necesidad del Gobierno (86.1); el decreto legislativo nace de una delegación previa y expresa de las Cortes (82.1). Origen distinto para dos normas con rango de ley."], "arts": [82, 86], "citas": [{"texto": "«En caso de extraordinaria y urgente necesidad, el Gobierno podrá dictar disposiciones legislativas provisionales que tomarán la forma de Decretos-leyes...»«Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas no incluidas en el artículo anterior.»", "fuente": "Artículo 86.1 CE · Artículo 82.1 CE"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}}, {"id": "ce-227", "origen": "otras", "test": "Test exámenes", "n": 134, "enunciado": "De conformidad con el artículo 85 de la Constitución, las disposiciones del Gobierno que contengan legislación delegada recibirán el título de:", "opciones": ["Decretos-leyes.", "Decretos Legislativos.", "Textos Refundidos.", "Reales Decretos."], "bloque": "t3-leyes", "precepto": "Artículo 85 CE", "correcta": 1, "justificaciones": ["No. Los Decretos-leyes son la figura del artículo 86, distinta de la legislación delegada.", "Es esta. Literal del artículo 85.", "No. «Texto Refundido» es el resultado material de una de las dos modalidades de delegación (82.2), no el nombre genérico de la norma.", "No. Real Decreto es la forma de las disposiciones reglamentarias ordinarias del Gobierno, sin rango de ley."], "arts": [85], "citas": [{"texto": "«Las disposiciones del Gobierno que contengan legislación delegada recibirán el título de Decretos Legislativos.»", "fuente": "Artículo 85 CE"}]}, {"id": "ce-228", "origen": "otras", "test": "Test exámenes", "n": 137, "enunciado": "Según lo dispuesto en el artículo 68.5 de la CE, son electores y elegibles todos los españoles que:", "opciones": ["Estén en pleno uso de sus derechos políticos.", "Hayan alcanzado la mayoría de edad.", "No hayan sido inhabilitados judicialmente.", "No hayan sido incapacitados civilmente."], "bloque": "t3-composicion", "precepto": "Artículo 68.5 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del 68.5.", "No. La mayoría de edad no es la fórmula del precepto, aunque esté implícita.", "No. La inhabilitación judicial no es la expresión que usa el artículo.", "No. Tampoco la incapacitación civil: la fórmula constitucional es «pleno uso de sus derechos políticos»."], "arts": [68], "citas": [{"texto": "«Son electores y elegibles todos los españoles que estén en pleno uso de sus derechos políticos.»", "fuente": "Artículo 68.5 CE"}], "marca": {"nivel": "clave", "nota": "Composición de las Cortes, el Congreso y el Senado: cifras que el INAP pregunta a menudo."}}, {"id": "ce-229", "origen": "otras", "test": "Test exámenes", "n": 138, "enunciado": "Según el artículo 73 de la CE, ¿quién puede solicitar que las Cámaras se reúnan en sesión extraordinaria?", "opciones": ["El Senado por mayoría simple.", "La Diputación Permanente.", "La Mesa del Senado.", "El Congreso por mayoría simple."], "bloque": "t3-composicion", "precepto": "Artículo 73.2 CE", "correcta": 1, "justificaciones": ["No. No basta la mayoría simple del Senado: hace falta la mayoría absoluta de sus miembros.", "Es esta. La Diputación Permanente es una de las tres vías del 73.2 (junto con el Gobierno y la mayoría absoluta de los miembros de una Cámara).", "No. La Mesa del Senado no está entre los legitimados del 73.2.", "No. Tampoco basta la mayoría simple del Congreso: se exige mayoría absoluta."], "arts": [73], "citas": [{"texto": "«Las Cámaras podrán reunirse en sesiones extraordinarias a petición del Gobierno, de la Diputación Permanente o de la mayoría absoluta de los miembros de cualquiera de las Cámaras.»", "fuente": "Artículo 73.2 CE"}], "truco": "Tres llaves para la sesión extraordinaria: el Gobierno, la Diputación Permanente, o la mayoría ABSOLUTA (no simple) de los miembros de cualquiera de las Cámaras."}, {"id": "ce-230", "origen": "otras", "test": "Test exámenes", "n": 139, "enunciado": "De acuerdo con el Título III de la CE, ¿se puede ser Diputado y Senador al mismo tiempo?", "opciones": ["Sí.", "No.", "Sólo si se es también miembro del Gobierno.", "Sólo si se es miembro de una Asamblea de Comunidad Autónoma."], "bloque": "t3-composicion", "precepto": "Artículo 67.1 CE", "correcta": 1, "justificaciones": ["No. Está prohibido.", "Es esta. El propio 67.1 lo prohíbe expresamente: nadie puede ser miembro de las dos Cámaras a la vez.", "No. Ser miembro del Gobierno no abre ninguna excepción a esta incompatibilidad entre Cámaras.", "No. Esa condición tampoco la excepciona: de hecho, el propio 67.1 prohíbe además acumular acta autonómica con la de Diputado."], "arts": [67], "citas": [{"texto": "«Nadie podrá ser miembro de las dos Cámaras simultáneamente, ni acumular el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso.»", "fuente": "Artículo 67.1 CE"}]}, {"id": "ce-231", "origen": "otras", "test": "Test exámenes", "n": 140, "enunciado": "Según el artículo 67 de la CE, los miembros de las Cortes Generales no estarán ligados por mandato:", "opciones": ["Potestativo.", "Imperativo.", "Autoritario.", "Preceptivo."], "bloque": "t3-composicion", "precepto": "Artículo 67.2 CE", "correcta": 1, "justificaciones": ["No. «Potestativo» no es la palabra del precepto.", "Es esta. Literal del 67.2: mandato imperativo, la palabra clave que consagra la representación libre del parlamentario frente a quien lo eligió.", "No. «Autoritario» tampoco.", "No. «Preceptivo» tampoco: la única que usa la Constitución es «imperativo»."], "arts": [67], "citas": [{"texto": "«Los miembros de las Cortes Generales no estarán ligados por mandato imperativo.»", "fuente": "Artículo 67.2 CE"}]}, {"id": "ce-232", "origen": "otras", "test": "Examen Tema 3", "n": 2, "enunciado": "Señale en qué plazo tiene el Rey que sancionar las leyes aprobadas por las Cortes Generales:", "opciones": ["Quince días.", "Veinte días.", "Un mes.", "Diez días."], "bloque": "t3-leyes", "precepto": "Artículo 91 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 91: quince días.", "No. Veinte días no es la cifra del 91.", "No. Un mes tampoco.", "No. Diez días tampoco: la cifra exacta es quince."], "arts": [91], "citas": [{"texto": "«El Rey sancionará en el plazo de quince días las leyes aprobadas por las Cortes Generales, y las promulgará y ordenará su inmediata publicación.»", "fuente": "Artículo 91 CE"}], "truco": "Quince días: el Rey sanciona, promulga y ordena publicar. Es un trámite reglado, sin margen de veto material."}, {"id": "ce-233", "origen": "otras", "test": "Test exámenes", "n": 144, "enunciado": "De acuerdo con la Constitución, señale cuál de las siguientes materias puede ser regulada a través de la iniciativa legislativa popular:", "opciones": ["Materias de carácter internacional.", "Materias propias del régimen de Seguridad Social.", "El régimen electoral general.", "Materias tributarias."], "bloque": "t3-leyes", "precepto": "Artículo 87.3 CE", "correcta": 1, "justificaciones": ["No. Las materias de carácter internacional están expresamente excluidas.", "Es esta. El 87.3 excluye expresamente lo tributario, lo internacional, lo de ley orgánica (como el régimen electoral general) y la prerrogativa de gracia; la Seguridad Social no figura en esa lista de exclusiones.", "No. El régimen electoral general es materia de ley orgánica (81.1) y también está excluido.", "No. Las materias tributarias están expresamente excluidas."], "arts": [87], "citas": [{"texto": "«Una ley orgánica regulará las formas de ejercicio y requisitos de la iniciativa popular para la presentación de proposiciones de ley. En todo caso se exigirán no menos de 500.000 firmas acreditadas. No procederá dicha iniciativa en materias propias de ley orgánica, tributarias o de carácter internacional, ni en lo relativo a la prerrogativa de gracia.»", "fuente": "Artículo 87.3 CE"}], "marca": {"nivel": "clave", "nota": "Legislación delegada e iniciativa legislativa (las 500.000 firmas): muy repetidos en los test y en el INAP."}, "truco": "Cuatro puertas cerradas a la iniciativa popular: ley orgánica, tributos, asuntos internacionales y prerrogativa de gracia (indultos). Lo que no esté en esa lista, en principio, sí cabe."}, {"id": "ce-234", "origen": "otras", "test": "Test exámenes", "n": 117, "enunciado": "Según el artículo 96 de la CE, los tratados internacionales, válidamente celebrados, formarán parte de nuestro ordenamiento:", "opciones": ["Cuando sean firmados por el Ministro de Asuntos Exteriores.", "Cuando sean ratificados por el Gobierno español.", "Cuando sean publicados oficialmente en España.", "Cuando sean autorizados por las Cortes Generales."], "bloque": "t3-tratados", "precepto": "Artículo 96.1 CE", "correcta": 2, "justificaciones": ["No. La sola firma del Ministro no basta para su entrada en vigor interna.", "No. La ratificación por el Gobierno tampoco es la condición que fija el precepto.", "Es esta. Literal del 96.1: la publicación oficial en España es la condición que integra el tratado en el ordenamiento interno.", "No. La autorización de las Cortes (cuando la exija el art.94) es un requisito previo para prestar el consentimiento, pero la incorporación al ordenamiento interno exige, además, la publicación oficial."], "arts": [96], "citas": [{"texto": "«Los tratados internacionales válidamente celebrados, una vez publicados oficialmente en España, formarán parte del ordenamiento interno.»", "fuente": "Artículo 96.1 CE"}]}, {"id": "ce-235", "origen": "otras", "test": "Test exámenes", "n": 146, "enunciado": "Las sesiones plenarias de las Cámaras:", "opciones": ["Serán públicas siempre, sin posibilidad de restringir esta condición.", "Serán a puerta cerrada si así lo deciden el Presidente de la Cámara o lo aconseja el contenido de las sesiones.", "Serán públicas, salvo acuerdo en contrario adoptado por mayoría absoluta en cada Cámara o con arreglo al Reglamento.", "Serán públicas, salvo acuerdo en contrario adoptado por mayoría simple en cada Cámara o con arreglo al Reglamento."], "bloque": "t3-composicion", "precepto": "Artículo 80 CE", "correcta": 2, "justificaciones": ["No. Sí cabe excepción, en los términos del propio artículo 80.", "No. No basta la sola voluntad del Presidente: hace falta acuerdo de la Cámara por mayoría absoluta o previsión del Reglamento.", "Es esta. Literal del artículo 80: la regla es la publicidad, y la excepción exige mayoría absoluta o previsión reglamentaria.", "No. La mayoría exigida es absoluta, no simple."], "arts": [80], "citas": [{"texto": "«Las sesiones plenarias de las Cámaras serán públicas, salvo acuerdo en contrario de cada Cámara, adoptado por mayoría absoluta o con arreglo al Reglamento.»", "fuente": "Artículo 80 CE"}]}, {"id": "ce-236", "origen": "otras", "test": "Test exámenes", "n": 149, "enunciado": "Según el artículo 84 de la Constitución Española, cuando una proposición de ley o una enmienda fuere contraria a una delegación legislativa en vigor:", "opciones": ["El Gobierno está facultado para oponerse a su tramitación.", "El Gobierno debe suspender la delegación legislativa hasta que se tramite esa proposición o esa enmienda.", "Queda en suspenso la delegación hasta que se tramite esa proposición o esa enmienda.", "El Gobierno puede dictar la correspondiente norma antes de que se tramite esa proposición o esa enmienda."], "bloque": "t3-leyes", "precepto": "Artículo 84 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 84: el Gobierno puede oponerse, no está obligado a suspender nada, y la delegación sigue vigente salvo que se derogue.", "No. El Gobierno no «debe» suspender: tiene la facultad de oponerse, que es distinto.", "No. La delegación no queda automáticamente en suspenso: sigue vigente mientras no se derogue.", "No. El artículo no habilita al Gobierno a adelantarse dictando la norma antes de la tramitación parlamentaria."], "arts": [84], "citas": [{"texto": "«Cuando una proposición de ley o una enmienda fuere contraria a una delegación legislativa en vigor, el Gobierno está facultado para oponerse a su tramitación. En tal supuesto, podrá presentarse una proposición de ley para la derogación total o parcial de la ley de delegación.»", "fuente": "Artículo 84 CE"}]}, {"id": "ce-237", "origen": "otras", "test": "Examen Tema 3", "n": 1, "enunciado": "De acuerdo con el artículo 90 de la CE, en los proyectos de ley declarados urgentes por el Gobierno o por el Congreso, el Senado dispondrá para vetar o enmendar estos proyectos de un plazo de:", "opciones": ["Dos meses.", "Un mes.", "Veinte días naturales.", "Quince días naturales."], "bloque": "t3-leyes", "precepto": "Artículo 90.3 CE", "correcta": 2, "justificaciones": ["No. Dos meses es el plazo ORDINARIO (90.2), no el de urgencia.", "No. Un mes no es la cifra del precepto.", "Es esta. Literal del 90.3: el plazo ordinario de dos meses se reduce a veinte días naturales cuando el proyecto se declara urgente.", "No. Quince días tampoco: la reducción es a veinte días naturales, no quince."], "arts": [90], "citas": [{"texto": "«El plazo de dos meses de que el Senado dispone para vetar o enmendar el proyecto se reducirá al de veinte días naturales en los proyectos declarados urgentes por el Gobierno o por el Congreso de los Diputados.»", "fuente": "Artículo 90.3 CE"}], "truco": "Senado y proyectos de ley: dos meses en procedimiento ordinario, veinte días naturales si el proyecto es urgente. El reloj arranca cuando el Senado RECIBE el texto, no cuando el Congreso lo remite."}, {"id": "ce-238", "origen": "otras", "test": "Test exámenes", "n": 159, "enunciado": "Según lo establecido en el artículo 90.2 de la Constitución Española, ¿con qué plazo cuenta el Senado, en el procedimiento ordinario, para vetar o enmendar un proyecto de ley remitido por el Congreso de los Diputados?", "opciones": ["El Senado dispondrá de dos meses a contar desde el día de la remisión del texto por el Congreso de los Diputados.", "El Senado dispondrá de dos meses a contar desde el día de la recepción del texto.", "El Senado dispondrá de tres meses a contar desde el día de la recepción del texto.", "El Senado dispondrá de tres meses a contar desde el día de la remisión del texto por el Congreso de los Diputados."], "bloque": "t3-leyes", "precepto": "Artículo 90.2 CE", "correcta": 1, "justificaciones": ["No. El cómputo empieza en la recepción por el Senado, no en la remisión por el Congreso: son dos actos distintos aunque próximos en el tiempo.", "Es esta. Literal del 90.2: dos meses desde la recepción del texto por el Senado, no desde su remisión por el Congreso.", "No. El plazo ordinario es de dos meses, no de tres.", "No. Combina los dos errores: ni tres meses ni remisión."], "arts": [90], "citas": [{"texto": "«El Senado en el plazo de dos meses, a partir del día de la recepción del texto, puede, mediante mensaje motivado, oponer su veto o introducir enmiendas al mismo.»", "fuente": "Artículo 90.2 CE"}]}, {"id": "ce-239", "origen": "otras", "test": "Test exámenes", "n": 152, "enunciado": "Los Diputados del Congreso y los Diputados de las Asambleas de Comunidades Autónomas:", "opciones": ["Pueden acumular el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso, en todo caso.", "Pueden acumular el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso, solo si lo permite expresamente el respectivo Estatuto de Autonomía.", "Pueden acumular el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso, solo si no lo prohíbe expresamente el respectivo Estatuto de Autonomía.", "No pueden acumular, en ningún caso, el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso."], "bloque": "t3-composicion", "precepto": "Artículo 67.1 CE", "correcta": 3, "justificaciones": ["No. Es justo lo contrario: la Constitución lo prohíbe.", "No. Ningún Estatuto puede autorizar lo que la Constitución prohíbe directamente.", "No. Tampoco hace falta que el Estatuto lo prohíba expresamente: la prohibición nace ya de la propia Constitución.", "Es esta. El propio 67.1 lo prohíbe «en todo caso», sin dejar margen a que los Estatutos de Autonomía lo autoricen o lo permitan."], "arts": [67], "citas": [{"texto": "«Nadie podrá ser miembro de las dos Cámaras simultáneamente, ni acumular el acta de una Asamblea de Comunidad Autónoma con la de Diputado al Congreso.»", "fuente": "Artículo 67.1 CE"}]}, {"id": "ce-240", "origen": "otras", "test": "Test exámenes", "n": 160, "enunciado": "Según el artículo 94 de la Constitución Española, los tratados internacionales de carácter político:", "opciones": ["Deben ser inmediatamente informados, una vez concluidos, al Congreso y al Senado.", "Requieren previa autorización de las Cortes Generales.", "Exigen una revisión constitucional previa.", "Deben adaptarse al ordenamiento jurídico mediante la aprobación en el Congreso por Ley Orgánica."], "bloque": "t3-tratados", "precepto": "Artículo 94.1 CE", "correcta": 1, "justificaciones": ["No. La simple información posterior a las Cámaras (94.2) es el régimen de los tratados que NO requieren autorización previa, no el de los políticos.", "Es esta. Los tratados políticos son la letra a) de la lista tasada del 94.1: exigen autorización previa de las Cortes Generales.", "No. La revisión constitucional previa es el supuesto distinto del artículo 95.1, para tratados contrarios a la Constitución.", "No. No se exige ley orgánica, sino autorización previa de las Cortes Generales."], "arts": [94], "citas": [{"texto": "«La prestación del consentimiento del Estado para obligarse por medio de tratados o convenios requerirá la previa autorización de las Cortes Generales, en los siguientes casos: a) Tratados de carácter político.»", "fuente": "Artículo 94.1 CE"}], "marca": {"nivel": "clave", "nota": "Tratados internacionales: qué necesita autorización por ley orgánica y cuáles solo de las Cortes. Ha caído en el INAP."}}, {"id": "ce-241", "origen": "otras", "test": "Test exámenes", "n": 155, "enunciado": "De conformidad con el artículo 94 de la Constitución Española, la prestación del consentimiento del Estado para obligarse por medio de tratados o convenios requerirá:", "opciones": ["En cualquier caso, la previa autorización de las Cortes Generales.", "La previa autorización de las Cortes Generales, en los supuestos tasados previstos en la Constitución.", "La previa autorización de las Cortes Generales, cuando se trate de tratados o convenios que contengan estipulaciones contrarias a la Constitución.", "Que el Congreso y el Senado sean inmediatamente informados de la conclusión de los tratados o convenios."], "bloque": "t3-tratados", "precepto": "Artículo 94.1 y 94.2 CE", "correcta": 1, "justificaciones": ["No. No es «en cualquier caso»: solo en los cinco supuestos del 94.1.", "Es esta. El 94.1 no exige autorización «en cualquier caso»: la reserva a cinco supuestos tasados (político, militar, integridad territorial/derechos del Título I, obligaciones financieras, modificación de ley); para el resto basta la información posterior del 94.2.", "No. Ese es el supuesto distinto del artículo 95.1 (previa revisión constitucional), no el régimen general del 94.", "No. Esa información posterior es precisamente lo que ocurre con los tratados que NO están en la lista del 94.1."], "arts": [94], "citas": [{"texto": "«La prestación del consentimiento del Estado para obligarse por medio de tratados o convenios requerirá la previa autorización de las Cortes Generales, en los siguientes casos: a) Tratados de carácter político. b) Tratados o convenios de carácter militar. c) Tratados o convenios que afecten a la integridad territorial del Estado o a los derechos y deberes fundamentales establecidos en el Título I. d) Tratados o convenios que impliquen obligaciones financieras para la Hacienda Pública. e) Tratados o convenios que supongan modificación o derogación de alguna ley o exijan medidas legislativas para su ejecución. El Congreso y el Senado serán inmediatamente informados de la conclusión de los restantes tratados o convenios.»", "fuente": "Artículo 94.1 y 94.2 CE"}], "marca": {"nivel": "clave", "nota": "Tratados internacionales: qué necesita autorización por ley orgánica y cuáles solo de las Cortes. Ha caído en el INAP."}}, {"id": "ce-242", "origen": "otras", "test": "Test exámenes", "n": 161, "enunciado": "En relación a la elaboración de las leyes, el Título III de la Constitución Española establece que:", "opciones": ["Las leyes de bases pueden facultar para dictar normas con carácter retroactivo.", "Las leyes de bases pueden autorizar la modificación de la propia ley de bases en supuestos excepcionales.", "La delegación legislativa podrá otorgarse al Gobierno de forma tácita para asuntos generales.", "La delegación legislativa se agota por el uso que de ella haga el Gobierno mediante la publicación de la norma correspondiente."], "bloque": "t3-leyes", "precepto": "Artículo 82.3 CE · Artículo 83 CE", "correcta": 3, "justificaciones": ["No. El artículo 83.b) prohíbe expresamente que la ley de bases faculte para dictar normas retroactivas.", "No. El artículo 83.a) prohíbe expresamente que la ley de bases autorice su propia modificación, sin excepciones.", "No. El 82.3 dice justo lo contrario: la delegación no puede entenderse concedida de modo implícito ni por tiempo indeterminado; debe ser expresa, para materia concreta y con plazo.", "Es esta. Literal del 82.3: un solo uso agota la delegación."], "arts": [82, 83], "citas": [{"texto": "«La delegación se agota por el uso que de ella haga el Gobierno mediante la publicación de la norma correspondiente. No podrá entenderse concedida de modo implícito o por tiempo indeterminado.»«Las leyes de bases no podrán en ningún caso: a) Autorizar la modificación de la propia ley de bases. b) Facultar para dictar normas con carácter retroactivo.»", "fuente": "Artículo 82.3 CE · Artículo 83 CE"}], "marca": {"nivel": "clave", "nota": "Legislación delegada e iniciativa legislativa (las 500.000 firmas): muy repetidos en los test y en el INAP."}}, {"id": "ce-243", "origen": "otras", "test": "Test exámenes", "n": 162, "enunciado": "Según el artículo 72 de la Constitución Española, las sesiones conjuntas del Congreso y del Senado se regirán:", "opciones": ["Por un Reglamento de las Cortes Generales aprobado por mayoría absoluta de cada Cámara.", "Por los Reglamentos respectivos de cada Cámara, aprobados por mayoría simple.", "Por un Reglamento de las Cortes Generales, aprobado por mayoría simple de cada Cámara.", "Por los Reglamentos respectivos de cada Cámara, aprobados por mayoría absoluta."], "bloque": "t3-composicion", "precepto": "Artículo 72.2 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del 72.2: un único Reglamento de las Cortes Generales, para las sesiones conjuntas, aprobado por mayoría absoluta de cada Cámara por separado.", "No. No son los Reglamentos de cada Cámara, sino uno específico de las Cortes Generales, y la mayoría exigida es absoluta.", "No. La mayoría exigida es absoluta, no simple.", "No. No son los Reglamentos de cada Cámara para este supuesto, sino el Reglamento conjunto de las Cortes Generales."], "arts": [72], "citas": [{"texto": "«Las sesiones conjuntas serán presididas por el Presidente del Congreso y se regirán por un Reglamento de las Cortes Generales aprobado por mayoría absoluta de cada Cámara.»", "fuente": "Artículo 72.2 CE"}], "truco": "Hay tres reglamentos distintos: el del Congreso, el del Senado, y el de las Cortes Generales (solo para sesiones conjuntas), este último aprobado por mayoría absoluta de cada Cámara."}, {"id": "ce-244", "origen": "otras", "test": "Test exámenes", "n": 168, "enunciado": "Señale la afirmación correcta en relación con la iniciativa legislativa, de conformidad con el artículo 87 de la CE:", "opciones": ["La iniciativa legislativa corresponde al Gobierno, al Congreso, al Senado y al Defensor del Pueblo, de acuerdo con la Constitución y los Reglamentos de las Cámaras.", "No procederá la iniciativa legislativa popular en materias que afecten a los derechos, deberes y libertades de los ciudadanos regulados en el Título I.", "Se exigirán, en todo caso, no menos de 500.000 firmas acreditadas para el ejercicio de la iniciativa legislativa popular.", "Las Asambleas de las Comunidades Autónomas podrán solicitar del Gobierno la adopción de un proyecto de ley o remitir a la Mesa del Congreso una proposición de ley, delegando ante dicha Cámara un máximo de dos miembros de la Asamblea encargados de su defensa."], "bloque": "t3-leyes", "precepto": "Artículo 87.3 CE", "correcta": 2, "justificaciones": ["No. La iniciativa legislativa corresponde al Gobierno, al Congreso, al Senado (87.1) y a las Asambleas de las Comunidades Autónomas (87.2); el Defensor del Pueblo no está en la lista.", "No. La exclusión del 87.3 es por razón de materia (ley orgánica, tributaria, internacional, gracia), no por afectar en general a los derechos del Título I.", "Es esta. Literal del 87.3: en todo caso, no menos de 500.000 firmas acreditadas.", "No. El máximo son tres miembros de la Asamblea, no dos (87.2)."], "arts": [87], "citas": [{"texto": "«Una ley orgánica regulará las formas de ejercicio y requisitos de la iniciativa popular para la presentación de proposiciones de ley. En todo caso se exigirán no menos de 500.000 firmas acreditadas.»", "fuente": "Artículo 87.3 CE"}], "marca": {"nivel": "clave", "nota": "Legislación delegada e iniciativa legislativa (las 500.000 firmas): muy repetidos en los test y en el INAP."}}, {"id": "ce-245", "origen": "otras", "test": "Test exámenes", "n": 157, "enunciado": "Según el Título III «De las Cortes Generales» de la Constitución Española:", "opciones": ["Las Cámaras podrán recibir peticiones individuales y colectivas, siempre por escrito, quedando prohibida la presentación directa por manifestaciones ciudadanas.", "Las Cámaras podrán delegar en las Comisiones Legislativas Permanentes la aprobación de proyectos o proposiciones de ley relativas a cuestiones internacionales.", "Las Cámaras podrán reunirse en sesión extraordinaria a petición de la mayoría simple de los miembros de cualquiera de las Cámaras.", "Las Cámaras conjuntamente podrán nombrar Comisiones de Investigación sobre asuntos de interés público y sus decisiones serán vinculantes para los Tribunales."], "bloque": "t3-composicion", "precepto": "Artículo 77.1 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del 77.1.", "No. Las cuestiones internacionales están expresamente excluidas de la delegación en Comisiones (75.3).", "No. Hace falta mayoría absoluta de los miembros de la Cámara, no mayoría simple (73.2).", "No. Las conclusiones de las Comisiones de Investigación no son vinculantes para los Tribunales (76.1)."], "arts": [77], "citas": [{"texto": "«Las Cámaras pueden recibir peticiones individuales y colectivas, siempre por escrito, quedando prohibida la presentación directa por manifestaciones ciudadanas.»", "fuente": "Artículo 77.1 CE"}]}, {"id": "ce-246", "origen": "otras", "test": "Examen Tema 3", "n": 20, "enunciado": "Según el Título III de la Constitución Española de 1978, las Cortes Generales:", "opciones": ["Ejercen el poder ejecutivo del Estado y aprueban sus Presupuestos.", "Controlan la acción del Gobierno.", "Son elegidas por sufragio universal, libre, indirecto y secreto.", "Se rigen por sus Reglamentos, aprobados por el Consejo de Ministros."], "bloque": "t3-composicion", "precepto": "Artículo 66.1 y 66.2 CE", "correcta": 1, "justificaciones": ["No. Ejercen la potestad LEGISLATIVA, no la ejecutiva, que corresponde al Gobierno (art.97).", "Es esta. Literal del 66.2: controlan la acción del Gobierno.", "No. El sufragio para elegir el Congreso es directo (68.1), no indirecto.", "No. Cada Cámara aprueba autónomamente su propio Reglamento (72.1); el Consejo de Ministros no interviene."], "arts": [66], "citas": [{"texto": "«Las Cortes Generales representan al pueblo español y están formadas por el Congreso de los Diputados y el Senado. Las Cortes Generales ejercen la potestad legislativa del Estado, aprueban sus Presupuestos, controlan la acción del Gobierno y tienen las demás competencias que les atribuya la Constitución.»", "fuente": "Artículo 66.1 y 66.2 CE"}], "marca": {"nivel": "clave", "nota": "Composición de las Cortes, el Congreso y el Senado: cifras que el INAP pregunta a menudo."}}, {"id": "ce-247", "origen": "otras", "test": "Examen Tema 3", "n": 18, "enunciado": "De acuerdo con lo establecido en el artículo 95 de la Constitución Española, ¿qué órganos pueden requerir al Tribunal Constitucional para que declare si existe o no contradicción de un tratado internacional con la Constitución?", "opciones": ["El Gobierno, las Cámaras y las Asambleas Legislativas de las Comunidades Autónomas.", "Sólo el Congreso de los Diputados, por mayoría absoluta de sus miembros.", "Sólo el Congreso y el Senado por mayoría de tres quintos de sus miembros.", "El Gobierno o cualquiera de las Cámaras."], "bloque": "t3-tratados", "precepto": "Artículo 95.2 CE", "correcta": 3, "justificaciones": ["No. Las Asambleas de las Comunidades Autónomas no están legitimadas por este precepto.", "No. No es solo el Congreso, ni se exige mayoría absoluta para este requerimiento.", "No. Cada Cámara puede requerir por separado; no hace falta actuación conjunta ni mayoría de tres quintos.", "Es esta. Literal del 95.2: solo el Gobierno o cualquiera de las Cámaras, sin exigir mayorías cualificadas ni intervención autonómica."], "arts": [95], "citas": [{"texto": "«El Gobierno o cualquiera de las Cámaras puede requerir al Tribunal Constitucional para que declare si existe o no esa contradicción.»", "fuente": "Artículo 95.2 CE"}]}, {"id": "ce-248", "origen": "otras", "test": "Examen Tema 3", "n": 9, "enunciado": "¿Qué proyectos o proposiciones de ley NO podrán ser objeto de delegación de las Cámaras en las Comisiones Legislativas Permanentes para su aprobación, según el artículo 75.3 de la CE?", "opciones": ["Las leyes de contenido económico.", "Las leyes que modifiquen leyes ya aprobadas y en vigor.", "Las leyes de bases.", "Las leyes que supongan la imposición directa de obligaciones a los ciudadanos."], "bloque": "t3-composicion", "precepto": "Artículo 75.3 CE", "correcta": 2, "justificaciones": ["No. El «contenido económico» en general no es una de las cuatro categorías excluidas.", "No. Modificar leyes en vigor tampoco excluye por sí solo la delegación.", "Es esta. La lista cerrada del 75.3 incluye reforma constitucional, cuestiones internacionales, leyes orgánicas y de bases, y Presupuestos Generales del Estado; ni el contenido económico en general, ni modificar leyes vigentes, ni imponer obligaciones son, por sí solos, causa de exclusión.", "No. Tampoco lo hace, por sí sola, la imposición de obligaciones a los ciudadanos."], "arts": [75], "citas": [{"texto": "«Quedan exceptuados de lo dispuesto en el apartado anterior la reforma constitucional, las cuestiones internacionales, las leyes orgánicas y de bases y los Presupuestos Generales del Estado.»", "fuente": "Artículo 75.3 CE"}], "truco": "Cuatro materias, siempre las mismas, blindadas frente a la delegación en Comisión: reforma constitucional, cuestiones internacionales, leyes orgánicas y de bases, y los Presupuestos Generales del Estado."}, {"id": "ce-249", "origen": "otras", "test": "Examen Tema 3", "n": 3, "enunciado": "Según el artículo 95.1 de la CE, la celebración de un tratado internacional que contenga estipulaciones contrarias a la Constitución:", "opciones": ["Exigirá la previa revisión constitucional.", "Exigirá su aprobación por Ley Orgánica.", "Exigirá la autorización del Tribunal Constitucional.", "En ningún caso puede celebrarse."], "bloque": "t3-tratados", "precepto": "Artículo 95.1 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del 95.1: primero se reforma la Constitución, y solo entonces cabe celebrar el tratado.", "No. No basta una ley orgánica: la contradicción con la Constitución exige reformarla primero.", "No. El Tribunal Constitucional puede ser requerido para declarar si existe la contradicción (95.2), pero no «autoriza» el tratado; lo que exige el 95.1 es la revisión constitucional.", "No. Sí puede celebrarse, una vez hecha la previa revisión constitucional."], "arts": [95], "citas": [{"texto": "«La celebración de un tratado internacional que contenga estipulaciones contrarias a la Constitución exigirá la previa revisión constitucional.»", "fuente": "Artículo 95.1 CE"}]}, {"id": "ce-250", "origen": "otras", "test": "Examen Tema 3", "n": 4, "enunciado": "De conformidad con el artículo 64 de la CE, la propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendadas por:", "opciones": ["El Rey.", "Los Presidentes del Congreso y del Senado.", "El Presidente del Congreso.", "El Rey y los ministros competentes."], "bloque": "t3-composicion", "precepto": "Artículo 64.1 CE", "correcta": 2, "justificaciones": ["No. El Rey no se refrenda a sí mismo: todo acto suyo necesita el refrendo de otro.", "No. No son los dos Presidentes conjuntamente, solo el del Congreso.", "Es esta. Es la única excepción a la regla general de refrendo (Presidente del Gobierno o ministros): estos dos actos concretos (propuesta/nombramiento del Presidente del Gobierno y la disolución del 99) los refrenda el Presidente del Congreso.", "No. Esa es la regla general para el resto de actos del Rey (64.1, primera frase), no la de estos dos actos concretos."], "arts": [64], "citas": [{"texto": "«Los actos del Rey serán refrendados por el Presidente del Gobierno y, en su caso, por los Ministros competentes. La propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendados por el Presidente del Congreso.»", "fuente": "Artículo 64.1 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}}, {"id": "ce-251", "origen": "otras", "test": "Examen Tema 3", "n": 6, "enunciado": "De conformidad con el artículo 68 de la CE, el Congreso electo deberá ser convocado:", "opciones": ["Dentro de los quince días siguientes a la celebración de las elecciones.", "Dentro de los veinte días siguientes a la celebración de las elecciones.", "Dentro de los veinticinco días siguientes a la celebración de las elecciones.", "Dentro de los treinta días siguientes a la celebración de las elecciones."], "bloque": "t3-composicion", "precepto": "Artículo 68.6 CE", "correcta": 2, "justificaciones": ["No. Quince no es la cifra del precepto.", "No. Veinte tampoco.", "Es esta. Literal del 68.6: veinticinco días.", "No. Treinta es el plazo mínimo para convocar elecciones tras acabar el mandato, no el de convocatoria del Congreso electo."], "arts": [68], "citas": [{"texto": "«Las elecciones tendrán lugar entre los treinta días y sesenta días desde la terminación del mandato. El Congreso electo deberá ser convocado dentro de los veinticinco días siguientes a la celebración de las elecciones.»", "fuente": "Artículo 68.6 CE"}], "marca": {"nivel": "clave", "nota": "Composición de las Cortes, el Congreso y el Senado: cifras que el INAP pregunta a menudo."}}, {"id": "ce-252", "origen": "otras", "test": "Examen Tema 3", "n": 7, "enunciado": "En una Comunidad Autónoma que tuviera dos provincias no insulares y un millón y medio de habitantes, ¿cuántos Senadores, elegidos y designados, en total, procederían de esa Comunidad Autónoma, de acuerdo con las reglas del artículo 69 de la CE?", "opciones": ["Diez.", "Once.", "Doce.", "Trece."], "bloque": "t3-composicion", "precepto": "Artículo 69.2 CE · Artículo 69.5 CE", "correcta": 0, "justificaciones": ["Es esta. Dos provincias no insulares dan 4 Senadores cada una (69.2): 8 en total. La Comunidad Autónoma designa, además, un Senador y otro más por cada millón de habitantes (69.5): con un millón y medio, corresponden 2 más. Total: 8 + 2 = 10.", "No. Once no cuadra con la suma exacta de electos (8) y designados (2).", "No. Doce tampoco.", "No. Trece tampoco: la cuenta correcta da diez."], "arts": [69], "citas": [{"texto": "«En cada provincia se elegirán cuatro Senadores...»«Las Comunidades Autónomas designarán además un Senador y otro más por cada millón de habitantes de su respectivo territorio.»", "fuente": "Artículo 69.2 CE · Artículo 69.5 CE"}], "marca": {"nivel": "clave", "nota": "Composición de las Cortes, el Congreso y el Senado: cifras que el INAP pregunta a menudo."}, "truco": "Separa siempre los dos grupos del artículo 69: los Senadores ELECTOS (4 por provincia, o los de las islas) y los DESIGNADOS por la Comunidad Autónoma (1 + 1 por millón de habitantes). Súmalos al final."}, {"id": "ce-253", "origen": "otras", "test": "Examen Tema 3", "n": 13, "enunciado": "De acuerdo con la Constitución Española, ¿cuántos Senadores elige la población de La Gomera?", "opciones": ["1 Senador.", "2 Senadores.", "3 Senadores.", "4 Senadores."], "bloque": "t3-composicion", "precepto": "Artículo 69.3 CE", "correcta": 0, "justificaciones": ["Es esta. La Gomera es una de las ocho islas menores del 69.3: le corresponde un Senador.", "No. Dos no es la cifra de ninguna isla del 69.3.", "No. Tres es la cifra de las tres islas mayores (Gran Canaria, Mallorca, Tenerife), no de La Gomera.", "No. Cuatro es la cifra por provincia (69.2), no por isla."], "arts": [69], "citas": [{"texto": "«En las provincias insulares, cada isla con Cabildo o Consejo Insular constituirá una circunscripción a efectos de elección de Senadores, correspondiendo tres a cada una de las islas mayores −Gran Canaria, Mallorca y Tenerife− y uno a cada una de las siguientes islas: Ibiza, Formentera, Menorca, Fuerteventura, La Gomera, El Hierro, Lanzarote y La Palma.»", "fuente": "Artículo 69.3 CE"}], "marca": {"nivel": "clave", "nota": "Composición de las Cortes, el Congreso y el Senado: cifras que el INAP pregunta a menudo."}, "truco": "Solo tres islas tienen tres Senadores: Gran Canaria, Mallorca y Tenerife. Las otras ocho (incluida La Gomera) tienen uno cada una."}, {"id": "ce-254", "origen": "otras", "test": "Examen Tema 3", "n": 14, "enunciado": "Según el artículo 115 de la Constitución Española, la disolución de las Cortes ha de proponerla:", "opciones": ["La mayoría absoluta del Congreso.", "La mayoría absoluta de las dos Cámaras.", "El Presidente del Gobierno.", "El Rey."], "bloque": "t3-control", "precepto": "Artículo 115.1 CE", "correcta": 2, "justificaciones": ["No. El Congreso no propone su propia disolución por esta vía.", "No. Tampoco las dos Cámaras conjuntamente.", "Es esta. La propuesta es del Presidente del Gobierno, bajo su exclusiva responsabilidad; el Rey se limita a decretarla.", "No. El Rey decreta la disolución, pero no la propone: la propuesta es del Presidente del Gobierno."], "arts": [115], "citas": [{"texto": "«El Presidente del Gobierno, previa deliberación del Consejo de Ministros, y bajo su exclusiva responsabilidad, podrá proponer la disolución del Congreso, del Senado o de las Cortes Generales, que será decretada por el Rey.»", "fuente": "Artículo 115.1 CE"}], "truco": "En la disolución del artículo 115, el Presidente del Gobierno PROPONE y el Rey DECRETA. No confundir con la disolución automática del artículo 99, donde no hay propuesta previa del Presidente."}, {"id": "ce-255", "origen": "otras", "test": "Examen Tema 3", "n": 15, "enunciado": "Según la Constitución Española, indique la respuesta correcta en relación con las leyes orgánicas:", "opciones": ["La aprobación, modificación o derogación de las leyes orgánicas exigirá la mayoría simple del Congreso, en una votación final sobre el conjunto del proyecto.", "La aprobación, modificación o derogación de las leyes orgánicas exigirá la mayoría absoluta del Congreso, en una votación final sobre el conjunto del proyecto.", "La aprobación, modificación o derogación de las leyes orgánicas exigirá la mayoría absoluta de ambas Cámaras.", "La aprobación, modificación o derogación de las leyes orgánicas exigirá la mayoría simple de ambas Cámaras."], "bloque": "t3-leyes", "precepto": "Artículo 81.2 CE", "correcta": 1, "justificaciones": ["No. No es mayoría simple, sino absoluta.", "Es esta. Literal del 81.2: mayoría absoluta, solo del Congreso, en votación final de conjunto.", "No. No se exige a ambas Cámaras, solo al Congreso.", "No. Combina los dos errores: ni simple ni de ambas Cámaras."], "arts": [81], "citas": [{"texto": "«La aprobación, modificación o derogación de las leyes orgánicas exigirá mayoría absoluta del Congreso, en una votación final sobre el conjunto del proyecto.»", "fuente": "Artículo 81.2 CE"}], "marca": {"nivel": "estrella", "nota": "Ley orgánica y decreto-ley: de lo que más se repite en el INAP (el 86 es el artículo con más preguntas oficiales del banco)."}}, {"id": "ce-256", "origen": "otras", "test": "Examen Tema 3", "n": 16, "enunciado": "De acuerdo con lo dispuesto en el artículo 67 de la Constitución Española, las reuniones de Parlamentarios que se celebren sin convocatoria reglamentaria:", "opciones": ["Son ilegales y están prohibidas.", "No vincularán a las Cámaras, pero los Parlamentarios podrán ejercer sus funciones ostentando sus privilegios.", "No vincularán a las Cámaras, y los Parlamentarios no podrán ejercer sus funciones ni ostentar sus privilegios.", "Vincularán a las Cámaras si asiste una mayoría de Parlamentarios de cada Cámara."], "bloque": "t3-composicion", "precepto": "Artículo 67.3 CE", "correcta": 2, "justificaciones": ["No. El precepto no las califica de «ilegales y prohibidas», sino que les niega efectos.", "No. Es justo lo contrario: tampoco pueden ejercer sus funciones ni ostentar sus privilegios.", "Es esta. Literal del 67.3: doble consecuencia, no vinculan a la Cámara y los parlamentarios pierden funciones y privilegios en ese contexto.", "No. Ninguna mayoría de asistentes puede sanar la falta de convocatoria reglamentaria."], "arts": [67], "citas": [{"texto": "«Las reuniones de Parlamentarios que se celebren sin convocatoria reglamentaria no vincularán a las Cámaras, y no podrán ejercer sus funciones ni ostentar sus privilegios.»", "fuente": "Artículo 67.3 CE"}]}]});
